/* mbstring costuma existir na Hostinger, mas quando falta o arquivo inteiro
   morre em branco — e numa TV isso é uma tela preta sem explicação.
   Fallback para as funções simples resolve com duas linhas. */
function _len($s){ return function_exists('mb_strlen') ? mb_strlen($s, 'UTF-8') : strlen($s); }
function _cut($s, $ini, $n){ return function_exists('mb_substr') ? mb_substr($s, $ini, $n, 'UTF-8') : substr($s, $ini, $n); }

