/* ── Cache no banco ─────────────────────────────────────────── */
/* Delegam para comum.php. Ficam como atalho para não reescrever as dezenas
   de chamadas espalhadas — o que multiplicaria o risco sem ganho nenhum. */
function cache_get($db, $chave, $ttl){
  if(function_exists('tvi_cache_ler')) return tvi_cache_ler($db, $chave, $ttl);
  return _cache_get_local($db, $chave, $ttl);
}
function _cache_get_local($db, $chave, $ttl){
  $c = $db->real_escape_string($chave);
  $r = $db->query("SELECT valor, atualizado_em FROM tvi_cache WHERE chave='$c' LIMIT 1");
  if(!$r || !$r->num_rows) return null;
  $x = $r->fetch_assoc();
  $idade = time() - strtotime($x['atualizado_em']);
  return array('dados' => json_decode($x['valor'], true), 'velho' => $idade > $ttl);
}

function cache_set($db, $chave, $valor){
  if(function_exists('tvi_cache_gravar')) return tvi_cache_gravar($db, $chave, $valor);
  return _cache_set_local($db, $chave, $valor);
}
function _cache_set_local($db, $chave, $valor){
  $c = $db->real_escape_string($chave);
  $v = $db->real_escape_string(json_encode($valor, JSON_UNESCAPED_UNICODE));
  $db->query("INSERT INTO tvi_cache (chave, valor, atualizado_em) VALUES ('$c','$v',NOW())
              ON DUPLICATE KEY UPDATE valor='$v', atualizado_em=NOW()");
}

function buscar_previsao($lat, $lon){
  $url = 'https://api.open-meteo.com/v1/forecast'
       . '?latitude='.$lat.'&longitude='.$lon
       . '&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,wind_speed_10m'
       . '&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max'
       . '&timezone=America%2FSao_Paulo&forecast_days=4';

  /* cURL PRIMEIRO, não file_get_contents.
     Em hospedagem compartilhada o allow_url_fopen costuma estar desligado,
     e aí o file_get_contents falha em silêncio. O plano B com cURL existia,
     mas só rodava se a primeira retornasse false — e em alguns servidores
     ela retorna string vazia, que não é false. Resultado: a previsão dizia
     "indisponível" todo dia num servidor que tinha cURL funcionando.
     Usar tvi_http quando existe resolve nos dois casos. */
  if(function_exists('tvi_http')){
    $raw = tvi_http($url, array('timeout' => 10));
  } elseif(function_exists('curl_init')){
    $ch = curl_init($url);
    curl_setopt_array($ch, array(
      CURLOPT_RETURNTRANSFER => 1, CURLOPT_TIMEOUT => 10,
      CURLOPT_CONNECTTIMEOUT => 6, CURLOPT_SSL_VERIFYPEER => 1,
      /* Mesmo motivo do comum.php: agente desconhecido leva 403 em vários
         veículos. */
      CURLOPT_USERAGENT => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) '
        . 'AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0 Safari/537.36'));
    $raw = curl_exec($ch);
    curl_close($ch);
  } else {
    $ctx = stream_context_create(array('http' => array('timeout' => 10, 'ignore_errors' => true)));
    $raw = @file_get_contents($url, false, $ctx);
  }

  if(!$raw) return null;
  $d = json_decode($raw, true);
  return (is_array($d) && isset($d['current'])) ? $d : null;
}

