/* ── Fontes de dados das extensões ─────────────────────────────
   Toda busca externa passa por aqui: uma requisição, cache no banco,
   e a TV nunca fala com ninguém de fora. Se a fonte cair, a última
   resposta boa continua no ar em vez de aparecer erro na parede. */

function cfg_valor($db, $chave, $padrao = ''){
  if(!$db) return $padrao;
  $c = $db->real_escape_string($chave);
  $r = $db->query("SELECT valor FROM tvi_config WHERE chave='$c' LIMIT 1");
  if($r && $r->num_rows) return $r->fetch_assoc()['valor'];
  return $padrao;
}

function buscar($url, $cabecalhos = array(), $segundos = 8){
  if(function_exists('curl_init')){
    $ch = curl_init($url);
    curl_setopt_array($ch, array(
      CURLOPT_RETURNTRANSFER => 1, CURLOPT_TIMEOUT => $segundos,
      CURLOPT_SSL_VERIFYPEER => 1, CURLOPT_HTTPHEADER => $cabecalhos,
      /* Mesmo motivo do comum.php: agente desconhecido leva 403 em vários
         veículos. */
      CURLOPT_USERAGENT => 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) '
        . 'AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0 Safari/537.36'));
    $r = curl_exec($ch);
    $ok = curl_getinfo($ch, CURLINFO_HTTP_CODE) < 400;
    curl_close($ch);
    return $ok ? $r : null;
  }
  $ctx = stream_context_create(array('http' => array(
    'timeout' => $segundos, 'ignore_errors' => true,
    'header' => implode("\r\n", $cabecalhos))));
  $r = @file_get_contents($url, false, $ctx);
  return $r ?: null;
}

/* Busca com cache: devolve o dado novo, ou o velho se a fonte falhar. */
function com_cache($db, $chave, $ttl, $buscador){
  $c = cache_get($db, $chave, $ttl);
  if($c && !$c['velho']) return $c['dados'];
  $novo = $buscador();
  if($novo !== null){ cache_set($db, $chave, $novo); return $novo; }
  return $c ? $c['dados'] : null;   // fonte fora do ar: vale o último bom
}

$db = null;
if(in_array($tipo, array('clima','futebol','seguranca','aniversarios','noticias','instagram','qualidade','redes','grupo','cotacao','agenda'), true)){
  $db = portal_db();
  if($db){
    $db->set_charset('utf8mb4');
    $db->query("CREATE TABLE IF NOT EXISTS tvi_cache (
      chave VARCHAR(120) PRIMARY KEY,
      valor LONGTEXT,
      atualizado_em DATETIME DEFAULT CURRENT_TIMESTAMP
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    $db->query("CREATE TABLE IF NOT EXISTS tvi_config (
      chave VARCHAR(60) PRIMARY KEY, valor VARCHAR(255) NOT NULL,
      atualizado_em DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
  }
}

$previsao = null;
if($tipo === 'clima'){
  if($db){

    $chave = 'clima:'.$cidade;
    $c = cache_get($db, $chave, 1800);          // 30 minutos

    if(!$c || $c['velho']){
      $novo = buscar_previsao($lat, $lon);
      if($novo){ cache_set($db, $chave, $novo); $previsao = $novo; }
      /* API fora do ar: segue com a última previsão boa, de QUALQUER idade.
         Antes o cache_get de 30 min já tinha devolvido null quando muito
         velho, então "última boa" na prática não existia. Previsão de
         3 horas atrás numa parede é melhor que "indisponível". */
      else {
        $velho = cache_get($db, $chave, 999999);
        if($velho) $previsao = $velho['dados'];
      }
    } else {
      $previsao = $c['dados'];
    }
  }
}

/* ── FUTEBOL ───────────────────────────────────────────────────
   Fonte: api-futebol.com.br, que é brasileira, documentada e tem plano
   grátis. Exige uma chave, colada em Configurações. Sem chave a extensão
   avisa em vez de quebrar a lista.

   O cache faz o trabalho pesado: o plano grátis é limitado, mas dez TVs
   pedindo a mesma tabela geram UMA chamada a cada 30 minutos. */
$fut = null; $futErro = null;
if($tipo === 'futebol'){
  $token = $db ? cfg_valor($db, 'futebol_token') : '';
  $camp  = $db ? (int)cfg_valor($db, 'futebol_campeonato', '10') : 10;
  $modo  = isset($_GET['modo']) ? preg_replace('/[^a-z]/','', $_GET['modo']) : 'hoje';

  if(!$token){
    $futErro = 'Falta a chave da API. Configurações, aba do TV Indoor.';
  } elseif(!$db){
    $futErro = 'Sem banco para guardar o cache.';
  } else {
    $cab = array('Authorization: Bearer '.$token);

    if($modo === 'tabela'){
      $fut = com_cache($db, "fut:tabela:$camp", 1800, function() use ($camp, $cab){
        $r = buscar("https://api.api-futebol.com.br/v1/campeonatos/$camp/tabela", $cab);
        $d = $r ? json_decode($r, true) : null;
        return is_array($d) && isset($d[0]['posicao']) ? $d : null;
      });
    } else {
      // "hoje" e "proximos" saem da mesma rodada atual: uma chamada só.
      $rod = com_cache($db, "fut:rodada:$camp", 300, function() use ($camp, $cab){
        $r = buscar("https://api.api-futebol.com.br/v1/campeonatos/$camp/rodadas", $cab);
        $d = $r ? json_decode($r, true) : null;
        if(!is_array($d)) return null;
        $atual = null;
        foreach($d as $x){ if(!empty($x['status']) && $x['status'] === 'em andamento'){ $atual = $x; break; } }
        if(!$atual) $atual = end($d);
        $slug = isset($atual['rodada']) ? $atual['rodada'] : 1;
        $r2 = buscar("https://api.api-futebol.com.br/v1/campeonatos/$camp/rodadas/$slug", $cab);
        $d2 = $r2 ? json_decode($r2, true) : null;
        return isset($d2['partidas']) ? $d2 : null;
      });
      $fut = $rod;
    }
    if($fut === null) $futErro = 'Não consegui falar com a fonte agora.';
  }
}

/* ── DIAS SEM ACIDENTE ─────────────────────────────────────────
   Nenhuma fonte externa. O número vem de uma data guardada no banco,
   e a conta é feita aqui. É a extensão mais barata e provavelmente a de
   maior efeito numa garagem. */
$seg = null;
if($tipo === 'seguranca' && $db){
  $desde  = cfg_valor($db, 'seguranca_desde', date('Y-m-d'));
  $recorde= (int)cfg_valor($db, 'seguranca_recorde', '0');
  $ts = strtotime($desde.' 00:00:00');
  $dias = $ts ? (int)floor((strtotime(date('Y-m-d').' 00:00:00') - $ts) / 86400) : 0;
  if($dias < 0) $dias = 0;
  // Passou o recorde: registra, para o próximo alvo já ser o novo número.
  if($dias > $recorde){
    $d2 = $db->real_escape_string((string)$dias);
    $db->query("INSERT INTO tvi_config (chave,valor) VALUES ('seguranca_recorde','$d2')
                ON DUPLICATE KEY UPDATE valor='$d2'");
    $recorde = $dias;
  }
  $seg = array('dias' => $dias, 'recorde' => $recorde, 'desde' => $desde);
}

/* ── ANIVERSARIANTES DO MÊS ────────────────────────────────────
   Lista cadastrada uma vez; o mês vira sozinho. Sem isso alguém tem que
   refazer a peça todo dia primeiro, e vai esquecer. */
$niver = null; $niverHoje = null;
if($tipo === 'aniversarios' && $db && (isset($_GET['modo']) && $_GET['modo'] === 'hoje')){
  /* Lista do dia, entregue por automação. Só vale se for de hoje: se o
     robô falhou de manhã, a tela não mostra a lista de ontem como se
     fosse a de hoje, que seria pior que não mostrar nada. */
  $bruto = cfg_valor($db, 'aniversarios_hoje', '');
  $d = $bruto ? json_decode($bruto, true) : null;
  if(is_array($d) && !empty($d['nomes']) && isset($d['data']) && $d['data'] === date('Y-m-d')){
    $niverHoje = $d;
  }
}
elseif($tipo === 'aniversarios' && $db){
  $bruto = cfg_valor($db, 'aniversarios', '');
  $mes = (int)date('n');
  $lista = array();
  foreach(explode("\n", str_replace("\r", '', $bruto)) as $l){
    $l = trim($l);
    if($l === '') continue;
    // formato: "12/03 Nome do colaborador"
    if(preg_match('/^(\d{1,2})\/(\d{1,2})\s+(.+)$/', $l, $m)){
      if((int)$m[2] === $mes) $lista[] = array('dia' => (int)$m[1], 'nome' => trim($m[3]));
    }
  }
  usort($lista, function($a, $b){ return $a['dia'] - $b['dia']; });
  $niver = $lista;
}

