/* ── Agenda por setor ─────────────────────────────────────────
   Um calendário do mês com os compromissos marcados, mais a lista ao lado.
   Quem passa vê a grade e acha a data; quem para lê a lista. */
$ag = null;
if($tipo === 'agenda' && $db){
  $setor = isset($_GET['setor']) ? preg_replace('/[^a-z]/', '', $_GET['setor']) : 'contabilidade';
  $mes   = date('Y-m');
  $se = $db->real_escape_string($setor);

  $itens = array();
  $r = $db->query("SELECT data, titulo, detalhe, cor FROM tvi_agenda
                   WHERE setor='$se' AND DATE_FORMAT(data,'%Y-%m')='$mes'
                   ORDER BY data, id");
  while($r && $x = $r->fetch_assoc()) $itens[] = $x;

  /* Vira o mês no dia 26: no fim do mês o que importa já é o mês seguinte,
     e uma parede mostrando um calendário que acabou não serve a ninguém. */
  if(!$itens && (int)date('j') >= 26){
    $mes = date('Y-m', strtotime('+1 month'));
    $r = $db->query("SELECT data, titulo, detalhe, cor FROM tvi_agenda
                     WHERE setor='$se' AND DATE_FORMAT(data,'%Y-%m')='$mes'
                     ORDER BY data, id");
    while($r && $x = $r->fetch_assoc()) $itens[] = $x;
  }

  $porDia = array();
  foreach($itens as $x) $porDia[(int)substr($x['data'], 8, 2)] = $x;

  $ag = array(
    'mes'     => $mes,
    'itens'   => $itens,
    'porDia'  => $porDia,
    'titulo'  => cfg_valor($db, 'agenda_titulo', 'Calendário Contábil'),
    'frase'   => cfg_valor($db, 'agenda_frase', ''),
    'rodape'  => cfg_valor($db, 'agenda_rodape', ''),
  );
}

/* ── Cotação ──────────────────────────────────────────────────
   Fonte: API de dados abertos do Banco Central (PTAX). É a taxa oficial,
   é pública, não exige cadastro nem chave, e não vai sair do ar por
   mudança comercial — que é o risco de qualquer serviço de terceiro.

   O PTAX é divulgado em boletins ao longo do dia e fecha por volta das
   13h. Fora do horário de mercado o valor é o do último fechamento, e a
   peça diz isso na tela: cotação sem data é cotação em que não se confia. */
$cot = null;
if($tipo === 'cotacao' && $db){
  $cot = tvi_com_cache($db, 'cotacao:ptax', 900, function(){
    $hoje = new DateTime('now', new DateTimeZone('America/Sao_Paulo'));
    // Busca 10 dias para trás: fim de semana e feriado não têm boletim.
    $de = clone $hoje; $de->modify('-10 days');
    $u = 'https://olinda.bcb.gov.br/olinda/servico/PTAX/versao/v1/odata/'
       . 'CotacaoDolarPeriodo(dataInicial=@d1,dataFinalCotacao=@d2)'
       . '?@d1=%27'.$de->format('m-d-Y').'%27&@d2=%27'.$hoje->format('m-d-Y').'%27'
       . '&$top=1&$orderby=dataHoraCotacao%20desc'
       . '&$format=json&$select=cotacaoCompra,cotacaoVenda,dataHoraCotacao';

    $r = function_exists('tvi_http') ? tvi_http($u, array('timeout'=>10)) : buscar($u, array(), 10);
    $d = $r ? json_decode($r, true) : null;
    if(empty($d['value'][0])) return null;

    $x = $d['value'][0];
    return array(
      'venda'  => (float)$x['cotacaoVenda'],
      'compra' => (float)$x['cotacaoCompra'],
      'quando' => $x['dataHoraCotacao'],
    );
  });

  /* Variação: guarda o valor do dia anterior para mostrar se subiu ou
     caiu. Um número sozinho não diz nada; com a seta, diz. */
  if($cot){
    $ant = tvi_cache_ler($db, 'cotacao:ontem', 999999);
    $hojeStr = substr($cot['quando'], 0, 10);
    if($ant && !empty($ant['dados']['dia']) && $ant['dados']['dia'] !== $hojeStr){
      $cot['antes'] = (float)$ant['dados']['venda'];
    } elseif($ant && !empty($ant['dados']['antes'])) {
      $cot['antes'] = (float)$ant['dados']['antes'];
    }
    if(!$ant || empty($ant['dados']['dia']) || $ant['dados']['dia'] !== $hojeStr){
      tvi_cache_gravar($db, 'cotacao:ontem', array(
        'dia' => $hojeStr, 'venda' => $cot['venda'],
        'antes' => isset($cot['antes']) ? $cot['antes'] : null));
    }
  }
}

/* ── Redes sociais ────────────────────────────────────────────
