    'youtube'   => array('YouTube',   'https://youtube.com/@%s'),
  );
  $temQr = @include_once __DIR__.'/qr.php';
  $redes = array('itens' => array(),
                 'chamada' => cfg_valor($db, 'rede_chamada', 'Acompanhe a gente'),
                 'site' => cfg_valor($db, 'rede_site', ''));

  foreach($mapa as $chave => $info){
