    if($perfil === '' && $chave === 'instagram') $perfil = cfg_valor($db, 'insta_arroba', '');
    if($perfil === '') continue;                 // rede não configurada: não aparece
    $url = sprintf($info[1], rawurlencode($perfil));
    $redes['itens'][] = array(
      'chave'  => $chave,
      'nome'   => $info[0],
      'perfil' => ($chave === 'linkedin' ? '' : '@').$perfil,
      'url'    => $url,
      'qr'     => ($temQr && function_exists('qr_data_uri'))
                  ? qr_data_uri($url, 5, '#0C0E1C', '#F1EFE7') : '',
    );
  }
  if($redes['site'] !== '' && $temQr && function_exists('qr_data_uri')){
