/* ── Política da Qualidade ────────────────────────────────────
   Vem do banco, não do código: estes textos passam por revisão formal
   (o "Rev.01" está lá por isso), e quem revisa não deve precisar de um
   programador para trocar uma palavra. */
$qa = null;
if($tipo === 'qualidade' && $db){
  $qa = array(
    'politica' => cfg_valor($db, 'qa_politica', ''),
    'rev'      => cfg_valor($db, 'qa_rev', ''),
    'missao'   => cfg_valor($db, 'qa_missao', ''),
    'visao'    => cfg_valor($db, 'qa_visao', ''),
    'valores'  => array_values(array_filter(array_map('trim',
                    preg_split('/[\r\n]+/', cfg_valor($db, 'qa_valores', ''))))),
  );
}

$insta = null; $instaErro = ''; $instaAviso = '';
$instaArroba = ''; $instaQR = '';
if($tipo === 'instagram'){
  $instaArroba = $db ? cfg_valor($db, 'insta_arroba', '') : '';
  if($instaArroba === '' && isset($_GET['arroba'])){
    $instaArroba = preg_replace('/[^A-Za-z0-9._]/', '', ltrim($_GET['arroba'], '@'));
  }
  /* O QR é gerado aqui, no servidor, e embutido como SVG. Sem serviço de
     fora: a parede não pode depender de um site de terceiro para desenhar
     um quadrado, nem enviar o perfil da empresa a cada exibição. */
  if($instaArroba !== '' && @include_once __DIR__.'/qr.php'){
    $instaQR = qr_data_uri('https://instagram.com/'.$instaArroba, 6, '#0C0E1C', '#F1EFE7');
  }
  $r = buscar(base_url_widget().'/tvindoor.php?action=insta_publico', array(), 12);
  $d = $r ? json_decode($r, true) : null;
  if($d && !empty($d['ok']) && !empty($d['posts'])){
    $insta = $d['posts'];
    if(!empty($d['aviso'])) $instaAviso = $d['aviso'];
  } else {
    $instaErro = ($d && !empty($d['erro'])) ? $d['erro'] : 'Sem resposta do servidor.';
  }
}

function base_url_widget(){
  $p = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';
  return $p.'://'.$_SERVER['HTTP_HOST'].rtrim(dirname($_SERVER['SCRIPT_NAME']), '/');
}
if($tipo === 'noticias' && $db){
  $feed = isset($_GET['feed']) ? $_GET['feed'] : cfg_valor($db, 'noticias_feed', '');
  if(!preg_match('#^https?://#i', $feed)){
    $newsErro = 'Nenhuma fonte configurada.';
  } else {
    /* O endereço descoberto fica guardado por um dia: descobrir a cada 15
       minutos seria pedir a página inteira do site só para reencontrar o
       que já se sabe. */
    $achado = com_cache($db, 'feedurl:'.md5($feed), 86400, function() use ($feed){
      list($u, $c) = descobrir_feed($feed);
      return $u ? array('url' => $u) : null;
    });
    $real = $achado && !empty($achado['url']) ? $achado['url'] : null;

    /* Rede caída: a descoberta do feed falha e $real fica nulo — e aí as
       notícias guardadas nunca eram consultadas, mesmo existindo. A peça
       mostrava "não encontrei feed" com meia hora de conteúdo bom no
       banco. Numa parede, notícia de uma hora atrás é melhor que aviso
       de erro técnico, que não diz nada a quem está esperando o ônibus. */
    if(!$real){
      $guardado = cache_get($db, 'rss:'.md5($feed), 999999);
      if(!$guardado){
        // Tenta também pela URL já descoberta antes, se houver.
        $antigo = cache_get($db, 'feedurl:'.md5($feed), 999999);
        if($antigo && !empty($antigo['dados']['url'])){
          $guardado = cache_get($db, 'rss:'.md5($antigo['dados']['url']), 999999);
        }
      }
      if($guardado && $guardado['dados']){
        $news = $guardado['dados'];
        $newsFonte = $feed;
        $newsVelho = true;      // a tela avisa que o conteúdo é de antes
      } else {
        $newsErro = 'Não encontrei feed em '.parse_url($feed, PHP_URL_HOST).
                    '. Use o botão Testar em Configurações para conferir o endereço.';
      }
    }

    if($real){
      $newsFonte = $real;
      $newsSeg = (int)cfg_valor($db, 'noticias_segundos', '18');
      $newsSeg = max(6, min(60, $newsSeg ?: 18));
      $antesDe = cache_get($db, 'rss:'.md5($real), 900);
      /* $db entra no use: a leitura do feed agora precisa dele para
         guardar as og:image que busca nas páginas das notícias. */
      $news = com_cache($db, 'rss:'.md5($real), 900, function() use ($real, $db){
        $xml = buscar($real, array(), 10);
        return $xml ? ler_feed($xml, $db) : null;
      });
      // Se o cache estava velho e a busca não trouxe nada, é conteúdo antigo.
      if($news && $antesDe && $antesDe['velho'] && $news === $antesDe['dados']) $newsVelho = true;
      if(!$news) $newsErro = 'A fonte respondeu, mas sem notícias aproveitáveis agora.';
    }
  }
}

/* ── Descoberta do feed ────────────────────────────────────────
   Chutar o endereço do RSS não funciona: cada site usa um caminho, e ele
   muda quando o site reformula. Mas todo site sério DECLARA o próprio feed
   no <head>, com <link rel="alternate" type="application/rss+xml">. É o
   mecanismo padrão, existe desde 2002, e ninguém usa.

   Então: aponte para a página que você lê no navegador, e o servidor acha
   o feed sozinho. Se a página for de uma seção (a tag de IA, por exemplo),
   ele acha o feed daquela seção. */

function parece_feed($txt){
  if(!$txt) return false;
  return (stripos($txt, '<rss') !== false)
      || (stripos($txt, '<feed') !== false && stripos($txt, 'atom') !== false)
      || (stripos($txt, '<channel') !== false && stripos($txt, '<item') !== false);
}

function resolver_url($href, $base){
  if(preg_match('#^https?://#i', $href)) return $href;
  $p = parse_url($base);
  $raiz = $p['scheme'].'://'.$p['host'].(isset($p['port']) ? ':'.$p['port'] : '');
  if(strpos($href, '//') === 0) return $p['scheme'].':'.$href;
  if(strpos($href, '/') === 0)  return $raiz.$href;
  $dir = isset($p['path']) ? preg_replace('#/[^/]*$#', '/', $p['path']) : '/';
  return $raiz.$dir.$href;
}

/* Devolve array(endereco_do_feed, conteudo) ou array(null, motivo). */
function descobrir_feed($url){
  $bruto = buscar($url, array(), 10);
  if($bruto && parece_feed($bruto)) return array($url, $bruto);

  // A página respondeu HTML: procura a declaração do feed no cabeçalho.
  if($bruto && stripos($bruto, '<html') !== false){
    $cabeca = substr($bruto, 0, 200000);
    if(preg_match_all('#<link[^>]+>#i', $cabeca, $tags)){
      $candidatos = array();
      foreach($tags[0] as $tag){
        if(stripos($tag, 'alternate') === false) continue;
        if(!preg_match('#type=["\']application/(rss|atom)\+xml["\']#i', $tag)) continue;
        if(preg_match('#href=["\']([^"\']+)["\']#i', $tag, $h)){
          $candidatos[] = resolver_url(html_entity_decode($h[1], ENT_QUOTES, 'UTF-8'), $url);
        }
      }
      // Feed de comentários é o primeiro em muito WordPress: deixa por último.
      usort($candidatos, function($a, $b){
        $ca = stripos($a, 'comment') !== false ? 1 : 0;
        $cb = stripos($b, 'comment') !== false ? 1 : 0;
        return $ca - $cb;
      });
      foreach(array_slice($candidatos, 0, 4) as $c){
        $t = buscar($c, array(), 10);
        if($t && parece_feed($t)) return array($c, $t);
      }
    }
  }

  // Último recurso: caminhos comuns.
  $base = rtrim($url, '/');
  foreach(array('/feed/', '/feed', '/rss', '/rss.xml', '/feed.xml', '/index.xml', '/atom.xml') as $suf){
    $c = $base.$suf;
    if($c === $url) continue;
    $t = buscar($c, array(), 8);
    if($t && parece_feed($t)) return array($c, $t);
  }

  return array(null, $bruto === null ? 'sem_resposta' : 'sem_feed');
}

/* ── Leitura de RSS com imagem e resumo ────────────────────────
   Feed brasileiro põe a foto em três lugares diferentes conforme o veículo:
   <enclosure>, <media:content>/<media:thumbnail>, ou um <img> solto dentro
   da descrição. Procuro nos três, na ordem de confiabilidade. Sem isso a
   extensão vira uma lista de títulos, que numa parede não segura ninguém. */
function ler_feed($xml, $db = null){
  $itens = array();

  if(function_exists('simplexml_load_string')){
    $ant = libxml_use_internal_errors(true);
    $x = simplexml_load_string($xml);
    libxml_use_internal_errors($ant);
    if($x){
      $nos = isset($x->channel->item) ? $x->channel->item : (isset($x->entry) ? $x->entry : array());
      $veiculo = isset($x->channel->title) ? trim((string)$x->channel->title) : '';

      foreach($nos as $i){
        /* content:encoded costuma ter o texto completo COM as imagens,
           enquanto description traz só o resumo sem foto. Muito veículo
           publica assim, e olhando só a description a peça fica sem imagem
           mesmo com a foto disponível no feed. */
        $ce = $i->children('http://purl.org/rss/1.0/modules/content/');
        $completo = isset($ce->encoded) ? (string)$ce->encoded : '';
        $desc = (string)(isset($i->description) ? $i->description
                       : (isset($i->summary) ? $i->summary
                       : (isset($i->content) ? $i->content : '')));

        $img = '';
        $origem = '';

        // 1. enclosure
        if(isset($i->enclosure['url']) &&
           (empty($i->enclosure['type']) || strpos((string)$i->enclosure['type'], 'image') !== false)){
          $img = (string)$i->enclosure['url']; $origem = 'enclosure';
        }
        // 2. media:content, media:thumbnail, e o media:group que envolve os dois
        if(!$img){
          $m = $i->children('http://search.yahoo.com/mrss/');
          if(isset($m->group->content[0]['url'])) { $img = (string)$m->group->content[0]['url']; $origem = 'media:group'; }
          elseif(isset($m->content['url']))      { $img = (string)$m->content['url'];  $origem = 'media:content'; }
          elseif(isset($m->thumbnail['url']))    { $img = (string)$m->thumbnail['url']; $origem = 'media:thumbnail'; }
        }
        // 3. <image> no item, usado por alguns agregadores
        if(!$img && isset($i->image)){
          $v = trim((string)$i->image);
          if(preg_match('#^https?://#i', $v)) { $img = $v; $origem = 'image'; }
        }
        // 4. dentro do HTML: primeiro no conteúdo completo, depois no resumo
        if(!$img){
          foreach(array($completo, $desc) as $html){
            $img = img_do_html($html);
            if($img){ $origem = 'html'; break; }
          }
        }

        $link = trim((string)(isset($i->link['href']) ? $i->link['href'] : $i->link));
        $texto = $desc !== '' ? $desc : $completo;

        $itens[] = montar_item((string)$i->title, $texto, $img,
          (string)(isset($i->pubDate) ? $i->pubDate : (isset($i->updated) ? $i->updated : '')),
          $veiculo, $link, $origem, $db);
        if(count($itens) >= 8) break;
      }
    }
  }

  // Plano B sem SimpleXML
  if(!$itens && preg_match_all('#<(?:item|entry)\b.*?</(?:item|entry)>#si', $xml, $blocos)){
    $veiculo = preg_match('#<channel>.*?<title[^>]*>(.*?)</title>#si', $xml, $ct) ? limpar($ct[1]) : '';
    foreach($blocos[0] as $b){
      $tit  = preg_match('#<title[^>]*>(.*?)</title>#si', $b, $t) ? $t[1] : '';
      $desc = preg_match('#<description[^>]*>(.*?)</description>#si', $b, $d) ? $d[1] : '';
      $ce   = preg_match('#<content:encoded[^>]*>(.*?)</content:encoded>#si', $b, $c2) ? $c2[1] : '';
      $lnk  = preg_match('#<link[^>]*>(.*?)</link>#si', $b, $l) ? trim($l[1]) : '';
      $img = ''; $origem = '';
      if(preg_match('#<enclosure[^>]+url=["\']([^"\']+)["\']#i', $b, $e)) { $img = $e[1]; $origem = 'enclosure'; }
      elseif(preg_match('#<media:(?:content|thumbnail)[^>]+url=["\']([^"\']+)["\']#i', $b, $e)) { $img = $e[1]; $origem = 'media'; }
      else { $img = img_do_html($ce ?: $desc); if($img) $origem = 'html'; }
      $dt = preg_match('#<pubDate[^>]*>(.*?)</pubDate>#si', $b, $p2) ? $p2[1] : '';
      if(trim($tit) !== '') $itens[] = montar_item($tit, $desc ?: $ce, $img, $dt, $veiculo, $lnk, $origem, $db);
      if(count($itens) >= 8) break;
    }
  }

  /* A og:image não é só último recurso: é a MELHOR fonte. Todo site a publica
     em 1200px porque serve à prévia do WhatsApp e do Facebook, enquanto o
     feed costuma apontar para a miniatura de 300px. Então busco a og:image
     quando não há imagem OU quando a que veio é pequena.
     Só nas quatro primeiras, que são as que vão ao ar antes do próximo ciclo:
     cada busca abre uma página do portal. */
  $buscas = 0;
  foreach($itens as $k => $it){
    if($it['link'] === '' || $buscas >= 4) continue;
    /* Quando a URL não declara o tamanho, o cabeçalho do arquivo declara:
       getimagesize baixa só os primeiros bytes. Sem isso, miniatura com nome
       limpo passava batida — que é o caso mais comum de todos, porque a CDN
       séria não põe dimensão na URL. */
    $larg = $it['img'] ? largura_provavel($it['img']) : 0;
    if($it['img'] !== '' && $larg === 0) $larg = largura_real($it['img']);
    $pequena = ($it['img'] === '') || ($larg > 0 && $larg < 900);
    if(!$pequena) continue;

    $buscas++;
    $og = og_image($it['link']);
    if(!$og) continue;
    // Só troca se a og for igual ou maior que a que já tenho.
    $lo = largura_provavel($og);
    if($it['img'] === '' || $lo === 0 || $lo >= $larg){
      $itens[$k]['img'] = $og;
      $itens[$k]['origem'] = $it['img'] === '' ? 'og:image' : 'og:image (troca)';
    }
  }

  // Passo final: pedir a versão grande de tudo que sobrou.
  foreach($itens as $k => $it){
    if($it['img']) $itens[$k]['img'] = pedir_maior($it['img']);
  }

  return $itens ?: null;
}

/* ── Qualidade da imagem ───────────────────────────────────────
   O feed quase sempre entrega MINIATURA. Um portal publica a mesma foto em
   várias larguras e o RSS aponta para a de 300px, porque foi pensado para
   leitor de feed num celular, não para uma TV de 55". Esticar 300px em
   1920 é o borrão que aparece na tela.

   Três frentes, em ordem de eficácia:
     1. entre os candidatos, escolher o de MAIOR largura declarada
     2. reescrever o parâmetro de redimensionamento da CDN quando existe
     3. preferir a og:image, que é feita para 1200px porque serve ao
        WhatsApp e ao Facebook
   O que sobrar de pequeno o player trata na hora de exibir. */

/* Tenta descobrir a largura pela própria URL: quase toda CDN a declara,
   seja como parâmetro (?w=300) ou no caminho (/300x200/). */
function largura_provavel($url){
  if(preg_match('#[?&](?:w|width|maxwidth|size)=(\d{2,5})#i', $url, $m)) return (int)$m[1];
  if(preg_match('#/(\d{3,5})x\d{2,5}/#', $url, $m)) return (int)$m[1];
  if(preg_match('#[-_](\d{3,4})x\d{2,4}\.(?:jpe?g|png|webp)#i', $url, $m)) return (int)$m[1];
  if(preg_match('#/(?:resize|thumb|thumbs|small|mini)/#i', $url)) return 240;
  return 0;   // desconhecida
}

/* Reescreve o pedido de tamanho para a CDN. Não inventa qualidade: pede ao
   servidor a versão grande da MESMA foto, que ele já tem. */
function pedir_maior($url){
  if(!$url) return $url;
  $alvo = 1600;

  // ?w=300 / ?width=300 / ?maxwidth=300
  $u = preg_replace_callback('#([?&](?:w|width|maxwidth)=)(\d{2,5})#i', function($m) use ($alvo){
    return (int)$m[2] < $alvo ? $m[1].$alvo : $m[0];
  }, $url);

  // ?h=200 acompanha, senão a CDN corta
  $u = preg_replace_callback('#([?&](?:h|height|maxheight)=)(\d{2,5})#i', function($m) use ($alvo){
    return (int)$m[2] < 900 ? $m[1].'900' : $m[0];
  }, $u);

  // /300x200/ no caminho
  $u = preg_replace_callback('#/(\d{3,5})x(\d{2,5})/#', function($m) use ($alvo){
    if((int)$m[1] >= $alvo) return $m[0];
    $prop = (int)$m[2] / max(1, (int)$m[1]);
    return '/'.$alvo.'x'.round($alvo * $prop).'/';
  }, $u);

  // qualidade baixa pedida na query
  $u = preg_replace('#([?&](?:q|quality)=)([1-6]\d)#i', '${1}85', $u);
  return $u;
}

/* Largura real, lida do cabeçalho do arquivo. Custa uma requisição, então
   só é usada quando a URL não diz nada e o resultado decide se vale buscar
   a og:image. O @ é porque imagem quebrada não pode derrubar a peça. */
function largura_real($url){
  if(!preg_match('#^https?://#i', $url)) return 0;
  $antes = ini_get('default_socket_timeout');
  @ini_set('default_socket_timeout', 6);
  $t = @getimagesize($url);
  @ini_set('default_socket_timeout', $antes);
  return ($t && !empty($t[0])) ? (int)$t[0] : 0;
}

/* Escolhe o melhor entre vários candidatos. */
function melhor_imagem($cands){
  $melhor = ''; $nota = -1;
  foreach($cands as $c){
    $u = trim($c);
    if($u === '' || stripos($u, 'data:image') === 0) continue;
    // descarta pixel de rastreamento e ícone
    if(preg_match('#(1x1|pixel|spacer|blank|avatar|logo|icon|favicon)#i', $u)) continue;
    $l = largura_provavel($u);
    $n = $l ?: 500;                       // sem informação: nota média
    if(preg_match('#\.svg($|\?)#i', $u)) $n = 100;
    if($n > $nota){ $nota = $n; $melhor = $u; }
  }
  return $melhor;
}

/* Procura TODAS as imagens de um pedaço de HTML e devolve a maior.
   Antes eu parava na primeira encontrada, e a primeira costuma ser o ícone
   do autor ou o selo do veículo. */
function img_do_html($html){
  if(!$html) return '';
  $cands = array();

  // lazy loading: o src real fica em data-src e o src é um pixel
  if(preg_match_all('#<img[^>]+(?:data-lazy-src|data-original|data-src)=["\']([^"\']+)["\']#i', $html, $m))
    foreach($m[1] as $x) $cands[] = $x;

  // srcset: cada entrada declara a largura, então dá para escolher a maior
  if(preg_match_all('#<img[^>]+srcset=["\']([^"\']+)["\']#i', $html, $m)){
    foreach($m[1] as $set){
      $maiorU = ''; $maiorW = -1;
      foreach(explode(',', $set) as $parte){
        $p = preg_split('/\s+/', trim($parte));
        if(empty($p[0])) continue;
        $w = (isset($p[1]) && preg_match('/(\d+)w/', $p[1], $mm)) ? (int)$mm[1] : 0;
        if($w > $maiorW){ $maiorW = $w; $maiorU = $p[0]; }
      }
      if($maiorU) $cands[] = $maiorU;
    }
  }

  if(preg_match_all('#<img[^>]+src=["\']([^"\']+)["\']#i', $html, $m))
    foreach($m[1] as $x) if(strlen($x) > 12) $cands[] = $x;

  if(preg_match_all('#url\((["\']?)([^"\')]+)\1\)#i', $html, $m))
    foreach($m[2] as $x) $cands[] = $x;

  return melhor_imagem($cands);
}

/* Lê a meta que os sites publicam para prévia em rede social. */
function og_image($url){
  if(!preg_match('#^https?://#i', $url)) return '';
  $html = buscar($url, array(), 6);
  if(!$html) return '';
  $cabeca = substr($html, 0, 120000);
  foreach(array('og:image:secure_url', 'og:image', 'twitter:image', 'twitter:image:src') as $prop){
    if(preg_match('#<meta[^>]+(?:property|name)=["\']'.preg_quote($prop, '#').'["\'][^>]*content=["\']([^"\']+)["\']#i', $cabeca, $m))
      return pedir_maior(resolver_url($m[1], $url));
    if(preg_match('#<meta[^>]+content=["\']([^"\']+)["\'][^>]*(?:property|name)=["\']'.preg_quote($prop, '#').'["\']#i', $cabeca, $m))
      return pedir_maior(resolver_url($m[1], $url));
  }
  return '';
}

function limpar($t){
  $t = preg_replace('#<!\[CDATA\[(.*?)\]\]>#s', '$1', $t);
  $t = strip_tags($t);
  $t = html_entity_decode($t, ENT_QUOTES, 'UTF-8');
  return trim(preg_replace('/\s+/u', ' ', $t));
}

/* A imagem vai para a TV pelo NOSSO servidor, não com o endereço do
   veículo.

   Antes ia o endereço original, e funcionava no navegador do computador
   mas falhava na parede. O box não é um navegador comum: alguns veículos
   recusam conexões que não reconhecem, outros bloqueiam por origem, e o
   WebView barra imagem em http quando a página é https.

   Passando pelo img.php, a TV pede ao servidor da empresa — que ela já
   alcança e já confia. E a imagem entra no cache do aparelho junto com o
   resto, então continua aparecendo se a internet cair. */
/* Busca a foto na PÁGINA da notícia quando o feed não traz.
   Alguns veículos — Jovem Pan entre eles — publicam feed sem enclosure,
   sem media:content e sem img no HTML. A foto existe, mas só na página.

   A og:image é a meta que todo site preenche para o WhatsApp e o Facebook
   mostrarem prévia. É a mesma imagem da manchete, e é o caminho que resta.

   Custo: uma busca extra por notícia. Por isso o resultado fica guardado
   por 6 horas — sem cache, seriam dez buscas a cada volta da peça. */
function img_da_pagina($db, $link){
  if(!$link || !preg_match('#^https?://#i', $link)) return '';

  $chave = 'ogimg_' . md5($link);
  $guardado = cache_get($db, $chave, 21600);
  if($guardado !== null && $guardado !== false) return (string)$guardado;

  $html = tvi_http($link, array('timeout' => 8));
  $img = '';
  if($html){
    /* og:image primeiro; twitter:image como segunda opção. A ordem dos
       atributos varia entre veículos, então aceita os dois sentidos. */
    if(preg_match('#<meta[^>]+property=["\']og:image["\'][^>]*content=["\']([^"\']+)#i', $html, $m)
    || preg_match('#<meta[^>]+content=["\']([^"\']+)["\'][^>]*property=["\']og:image#i', $html, $m)
    || preg_match('#<meta[^>]+name=["\']twitter:image["\'][^>]*content=["\']([^"\']+)#i', $html, $m)){
      $img = html_entity_decode(trim($m[1]), ENT_QUOTES, 'UTF-8');
    }
  }
  cache_set($db, $chave, $img);
  return $img;
}

function img_pelo_servidor($url){
  $url = trim((string)$url);
  if($url === '') return '';
  if(strpos($url, 'data:') === 0) return $url;          // já embutida
  if(!preg_match('#^https?://#i', $url)) return $url;   // relativa: deixa como está
  return tvi_base_url() . '/img.php?u=' . rawurlencode($url);
}

function montar_item($titulo, $desc, $img, $data, $veiculo, $link = '', $origem = '', $db = null){
  /* Se o feed não trouxe imagem, procura na página da notícia. */
  if(trim((string)$img) === '' && $link !== '' && $db) $img = img_da_pagina($db, $link);
  $img = img_pelo_servidor($img);
  $d = limpar($desc);
  // A descrição de muito feed repete o título na frente. Tira, senão a peça
  // mostra a mesma frase duas vezes, uma grande e outra pequena.
  $t = limpar($titulo);
  if($t !== '' && stripos($d, $t) === 0) $d = trim(substr($d, strlen($t)), " -–—:·");
  /* 150, não 220. A 3 metros de distância ninguém lê um parágrafo: o
     resumo serve para dar contexto à manchete, não para contar a matéria.
     Corta na última palavra inteira, senão a frase termina no meio. */
  if(_len($d) > 150){
    $d = _cut($d, 0, 150);
    // mbstring pode faltar: o resto do arquivo já trata, esta linha escapou.
    $ult = function_exists('mb_strrpos') ? mb_strrpos($d, ' ') : strrpos($d, ' ');
    $ult = $ult === false ? 0 : (int)$ult;
    if($ult > 90) $d = _cut($d, 0, $ult);
    $d = rtrim($d, " ,;:.").'…';
  }
  // Manchete monstruosa: alguns portais repetem o subtítulo no título.
  if(_len($t) > 120) $t = rtrim(_cut($t, 0, 120)).'…';

  $q = '';
  if($data){
    $ts = strtotime($data);
    if($ts){
      $h = time() - $ts;
      $q = $h < 3600 ? max(1, (int)($h/60)).' min atrás'
         : ($h < 86400 ? (int)($h/3600).'h atrás' : date('d/m', $ts));
    }
  }
  /* Protocolo relativo não resolve dentro do iframe: precisa de esquema.
     E numa página servida por https o navegador BLOQUEIA imagem http como
     conteúdo misto, então tentar https é a única chance de aparecer. Numa
     página http, mexer só atrapalharia. */
  $sob_https = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off');
  if($img && strpos($img, '//') === 0) $img = ($sob_https ? 'https:' : 'http:').$img;
  if($img && $sob_https && stripos($img, 'http://') === 0) $img = 'https://'.substr($img, 7);

  return array('titulo' => $t, 'texto' => $d, 'img' => $img, 'quando' => $q,
               'veiculo' => limpar($veiculo), 'link' => trim($link), 'origem' => $origem);
}

?><!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title><?php echo $tipo === 'clima' ? 'Previsão' : 'Relógio'; ?></title>
<style>
/* Tipografia dimensionada para leitura a 3–5 metros: é o que separa um
   painel de TV de uma página de navegador. Tudo em vw para acompanhar
   telas de 32" a 75" sem ajuste. */
*{margin:0;padding:0;box-sizing:border-box}

/* Quando a peça sai de vista, TODAS as animações param e o desfoque cai.
   O blur é a operação mais cara da peça de notícias: mantê-lo ligado numa
   camada invisível é desenhar para ninguém. */
body.fora *{animation-play-state:paused !important;
  transition:none !important}
body.fora .mat__fundo,body.fora .ig2__fundo{filter:none !important;opacity:.5}
body.fora .onda,body.fora .balao,body.fora .gp__anel{visibility:hidden}
html,body{height:100%;overflow:hidden;background:#0C0E1C;color:#F1EFE7;
  font-family:"Segoe UI Variable Text","Segoe UI",system-ui,-apple-system,
  "Helvetica Neue",Arial,sans-serif;
  font-variant-numeric:tabular-nums slashed-zero;font-kerning:normal;
  -webkit-font-smoothing:antialiased;cursor:none;user-select:none}
body:has(.aviso){background:#7A1224}
/* Azul da marca abrindo no canto superior, dourado sugerido embaixo.
   Uma tela de TV fica horas no mesmo quadro — precisa ter profundidade
   sem virar poluição. */
body{background:
  radial-gradient(1500px 780px at 80% -14%, #2A2F6C 0, transparent 62%),
  radial-gradient(900px 620px at -8% 110%, #221A0C 0, transparent 58%), #0C0E1C}
/* A marca ocupa o canto superior esquerdo, fora do fluxo do conteúdo — que
   fica centralizado verticalmente e por isso nunca esbarra nela. Altura em
   vw para acompanhar telas de 32" a 75" sem ajuste. */
/* Canto superior DIREITO. O relógio e a previsão ficam centrados no meio
   da tela, então a marca no canto oposto não disputa espaço com nada. */
.marca{position:fixed;top:3vw;right:5vw;height:5.2vw;width:auto;display:block;z-index:6}
.tela{height:100%;display:flex;flex-direction:column;justify-content:center;padding:4vw 5vw}

/* Relógio */
/* Centro da tela nos dois eixos. Antes o texto começava na margem
   esquerda e só parecia centrado por acaso do tamanho. */
.tela.rel{align-items:center;justify-content:center;text-align:center}
.hora{font-size:22vw;font-weight:200;line-height:.92;letter-spacing:-.02em;
  font-variant-numeric:tabular-nums}
.hora small{font-size:.28em;font-weight:300;color:#C08A28;margin-left:.15em}
/* capitalize maiúsculiza cada palavra e deixa "Sexta-Feira, 31 De Julho".
   Em português só a primeira letra sobe. */
.dia{font-size:3.4vw;font-weight:300;color:#ECDBAE;margin-top:1.4vw}
.dia::first-letter{text-transform:uppercase}
.sep{opacity:1;transition:opacity .4s}
.sep.off{opacity:.22}

/* Clima */
.tela.clm{align-items:center;justify-content:center}
.topo{display:flex;align-items:flex-end;gap:3vw;flex-wrap:wrap;justify-content:center}
.icone{font-size:11vw;line-height:1}
.temp{font-size:15vw;font-weight:200;line-height:.9;font-variant-numeric:tabular-nums}
.temp sup{font-size:.34em;font-weight:300;vertical-align:super}
.meta{padding-bottom:1.4vw}
/* Nome da cidade em serifa: é onde a peça "assina", como o wordmark. */
.cidade{font-size:2.6vw;color:#ECDBAE;font-weight:400;
  font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif}
.cond{font-size:3.4vw;font-weight:400;margin:.3vw 0}
.extra{font-size:1.7vw;color:#9EA2C0}
.dias{display:grid;grid-template-columns:repeat(3,1fr);gap:1.6vw;margin-top:4vw;
  border-top:1px solid rgba(236,219,174,.16);padding-top:3vw;width:100%;max-width:76vw}
.d{text-align:center}
.d .nome{font-size:1.9vw;color:#ECDBAE;text-transform:uppercase;letter-spacing:.1em}
.d .ic{font-size:5.4vw;line-height:1.25}
.d .tt{font-size:2.8vw;font-variant-numeric:tabular-nums}
.d .tt b{font-weight:500}
.d .tt span{color:#9EA2C0;font-weight:300}
.d .ch{font-size:1.5vw;color:#C08A28}
.rodape{position:fixed;left:0;right:0;bottom:2.2vw;text-align:center;
  font-size:1.3vw;color:#6A6F98}
/* Aviso urgente: fundo próprio, contraste alto. Quem passa tem dois
   segundos de atenção — a mensagem precisa vencer o ambiente. */
/* Vermelho profundo, não o vermelho do alerta de navegador. */
.aviso{background:#7A1224;justify-content:center;text-align:center}
.tarja{font-size:2vw;letter-spacing:.3em;text-transform:uppercase;color:#ECDBAE;
  margin-bottom:2vw;font-weight:600}
.msg{font-weight:400;line-height:1.22;color:#fff;max-width:88vw;margin:0 auto}

/* Extensões: mesma família das outras peças. Tudo em vw porque a mesma
   página roda numa 32 e numa 75 polegadas. */
.secao{font-size:1.7vw;letter-spacing:.24em;text-transform:uppercase;color:#C08A28;
  font-weight:600;margin-bottom:2.4vw}

.jogo{display:flex;align-items:center;gap:1.6vw;padding:1.5vw 0;
  border-bottom:1px solid rgba(236,219,174,.13);position:relative}
.jogo:last-child{border-bottom:0}
.jogo .lado{flex:1;display:flex;align-items:center;gap:1.1vw;min-width:0}
.jogo .lado.dir{justify-content:flex-end;text-align:right}
.jogo .lado img{height:3.6vw;width:auto;flex:0 0 auto}
.jogo .lado b{font-size:2.5vw;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.jogo .placar{font-family:ui-monospace,Consolas,monospace;font-size:4vw;font-weight:600;
  min-width:9vw;text-align:center;font-variant-numeric:tabular-nums}
.jogo .placar i{font-style:normal;color:#6A6F98;margin:0 .3vw}
.jogo .placar u{text-decoration:none;font-size:2.2vw;color:#ECDBAE;font-weight:400}
.jogo .sit{position:absolute;right:0;bottom:.2vw;font-size:1.1vw;letter-spacing:.16em;
  text-transform:uppercase;color:#6A6F98}
.jogo.vivo .sit{color:#57C98B;font-weight:700}
.jogo.vivo .placar{color:#57C98B}

.tab{width:100%;border-collapse:collapse;font-size:2.1vw}
.tab td{padding:.85vw .6vw;border-bottom:1px solid rgba(236,219,174,.1)}
.tab tr:last-child td{border-bottom:0}
.tab .pos{width:3vw;color:#6A6F98;font-family:ui-monospace,Consolas,monospace;text-align:right}
.tab .esc{width:3.4vw}
.tab .esc img{height:2.6vw;width:auto;display:block}
.tab .nome{font-weight:500}
.tab .pts{text-align:right;font-family:ui-monospace,Consolas,monospace;font-weight:700;
  color:#D9A83F;width:5vw;font-variant-numeric:tabular-nums}
.tab .min{text-align:right;font-family:ui-monospace,Consolas,monospace;color:#9EA2C0;
  width:4.5vw;font-size:1.7vw;font-variant-numeric:tabular-nums}
.rodape2{margin-top:1.6vw;font-size:1.2vw;color:#6A6F98;letter-spacing:.16em}

.seg{text-align:center}
.contador{font-size:26vw;line-height:.86;font-weight:200;color:#57C98B;
  font-variant-numeric:tabular-nums;letter-spacing:-.03em}
.contLegenda{font-size:3.4vw;font-weight:300;color:#EFEDE4;margin-top:1vw}
.alvo{font-size:1.9vw;color:#9EA2C0;margin-top:2.6vw}
.alvo b{color:#ECDBAE;font-weight:600}

/* ── Aniversariantes ──────────────────────────────────────────
   Balões animados só com CSS. Nada de biblioteca de partículas: isto roda
   em TV de 2017, e transform/opacity são as duas propriedades que a GPU
   acelera sozinha. Doze elementos custam praticamente nada. */
.baloes{position:fixed;inset:0;overflow:hidden;pointer-events:none;z-index:1}
.balao{position:absolute;bottom:-16vw;border-radius:50% 50% 48% 48%;
  opacity:.34;animation-name:subir;animation-timing-function:linear;
  animation-iteration-count:infinite;will-change:transform}
/* O barbante: um traço fino saindo da base. */
.balao::after{content:"";position:absolute;top:99%;left:50%;width:1px;height:5vw;
  background:linear-gradient(180deg,currentColor,transparent);opacity:.5}
@keyframes subir{
  0%   { transform:translate3d(0,0,0) rotate(-4deg); }
  50%  { transform:translate3d(2.4vw,-58vh,0) rotate(4deg); }
  100% { transform:translate3d(-1.4vw,-120vh,0) rotate(-3deg); }
}

/* Abertura: entra, respira 6 segundos e sai para a lista. */
.festa{position:fixed;inset:0;z-index:3;display:flex;flex-direction:column;
  align-items:center;justify-content:center;text-align:center;padding:9vh 14vw 9vh 10vw;
  box-sizing:border-box;
  animation:entrarFesta .8s cubic-bezier(.2,.8,.3,1) both}
.festa.saiu{animation:sairFesta .6s ease forwards;pointer-events:none}
@keyframes entrarFesta{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
@keyframes sairFesta{to{opacity:0;transform:scale(1.05)}}
.festa__sup{font-size:2vw;letter-spacing:.3em;text-transform:uppercase;color:#C08A28;
  font-weight:700;margin-bottom:2.4vw;animation:surgir .7s .15s both}
.festa__tit{font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
  font-size:8.4vw;font-weight:400;line-height:1.04;margin:0;letter-spacing:-.02em;
  animation:surgir .8s .3s both}
.festa__data{margin-top:2.4vw;font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
  font-size:3.4vw;color:#C08A28;font-weight:400;animation:surgir .8s .45s both;
  letter-spacing:.01em}
.festa__qtd{margin-top:1.2vw;font-size:2.2vw;color:#9EA2C0;font-weight:300;
  animation:surgir .8s .62s both}
@keyframes surgir{from{opacity:0;transform:translateY(1.6vw)}to{opacity:1;transform:none}}

/* Lista: entra depois da abertura. */
.tela.hoje{opacity:0;transition:opacity .7s ease;z-index:2;position:relative}
.tela.hoje.entrou{opacity:1}
.pgNiver{display:none}
.pgNiver.on{display:block;animation:surgir .6s both}

/* Um nome só merece a tela inteira; seis precisam caber. Duas faixas de
   tamanho, e acima disso a lista vira páginas em vez de encolher a fonte. */
/* MARGEM DE SEGURANÇA (title safe).
   TV corta as bordas — quanto varia por aparelho, e o overscan de fábrica
   chega a 5%. Texto encostado no canto some. O padrão de broadcast reserva
   10% de cada lado para texto, e é o que uso aqui. A coluna da direita
   ganha folga extra porque é onde fica a logo. */
.tela.hoje{align-items:center;justify-content:center;text-align:center;
  padding:9vh 14vw 9vh 10vw}
body.qualidade{background:
  radial-gradient(1500px 800px at 76% -18%,#2A2F6C 0,transparent 58%),
  radial-gradient(1100px 700px at -12% 112%,#1C1F45 0,transparent 54%),#0C0E1C}
body.niver{background:
  radial-gradient(1400px 720px at 78% -16%,#2E3478 0,transparent 60%),
  radial-gradient(1000px 620px at -10% 108%,#3A2A10 0,transparent 56%),#0C0E1C}
@media (prefers-reduced-motion:reduce){
  .balao{animation:none;display:none}
  .festa,.festa__sup,.festa__tit,.festa__qtd,.pgNiver.on{animation:none}
}
.nivHoje{display:flex;flex-direction:column;gap:1.2vh;width:100%;
  max-width:100%;overflow:hidden}
.nivHoje .nh{width:100%;overflow-wrap:break-word;hyphens:auto;
  /* O tamanho vem do script, que mede o nome real. Nome longo encolhe
     em vez de vazar; nome curto usa a tela toda. */
  font-size:var(--tam, 5vw);line-height:1.12}
/* Três faixas: um nome sozinho merece a tela inteira. */
/* As faixas fixas por quantidade SAÍRAM. Elas tinham especificidade maior
   que .nivHoje .nh, então venciam o tamanho calculado pelo script — e o
   ajuste que mede o nome real era simplesmente ignorado. Era por isso que
   os nomes continuavam grandes mesmo depois de reduzir os valores base.
   Agora o peso e a entrelinha ficam aqui; o TAMANHO vem só do script. */
/* !important aqui é deliberado, não preguiça: o tamanho é CALCULADO em
   tempo de execução medindo o nome real, e nenhuma regra de folha de
   estilo deve poder vencê-lo. Foi exatamente isso que aconteceu antes. */
.nivHoje .nh{font-weight:300}
.nivHoje .nh[style*="--tam"]{font-size:var(--tam) !important}
.nivHoje.muitos{display:grid;grid-template-columns:1fr 1fr;gap:.8vw 4vw;text-align:left}
.nivHoje.muitos .nh{padding-bottom:.6vw;border-bottom:1px solid rgba(236,219,174,.12)}
/* O cargo é contexto, não manchete: entra menor, em dourado pálido. */
.nivHoje .nh i{display:block;font-style:normal;color:#C08A28;font-weight:400;
  letter-spacing:.06em;margin-top:.35vw}
/* O cargo é proporção do nome, não número fixo: assim ele encolhe junto
   quando o script reduz o nome grande. */
.nivHoje .nh i{font-size:calc(var(--tam, 5vw) * .32)}
.parabens{margin-top:3.4vw;font-size:2.2vw;color:#ECDBAE;font-weight:300;
  font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif}

.nivers{display:grid;grid-template-columns:1fr 1fr;gap:1.1vw 4vw}
.niv{display:flex;align-items:baseline;gap:1.4vw;font-size:2.4vw;
  padding-bottom:.9vw;border-bottom:1px solid rgba(236,219,174,.1)}
.niv .dia{font-family:ui-monospace,Consolas,monospace;color:#C08A28;font-weight:700;
  font-size:2vw;flex:0 0 auto}

/* Manchete: foto ocupando a tela, véu para o texto sobreviver a qualquer
   imagem, e o conteúdo ancorado embaixo. É a gramática do telejornal, que
   é justamente o que a pessoa esperando ônibus já sabe ler. */
/* Sem foto a peça não pode ficar feia: fundo da marca e o texto sobe para
   o meio, virando um cartaz de manchete em vez de uma tela preta com letra
   no rodapé. */
.matéria{position:fixed;top:0;left:0;right:0;bottom:0;opacity:0;
  background-color:#0C0E1C;overflow:hidden;
  transition:opacity .7s ease;pointer-events:none}

/* Fundo: a mesma foto ampliada e desfocada. O desfoque disfarça a falta de
   resolução, e o scale evita a borda transparente que o blur cria. */
/* O desfoque é a operação mais cara da peça: 1600x900 borrados a cada
   quadro. Em Android de TV isso atrasou a primeira pintura em quase um
   segundo — que é o engasgo que aparece na troca de item.

   Solução: a peça pinta PRIMEIRO sem desfoque e o aplica logo depois, com
   uma transição curta. O olho não percebe a diferença; o processador sim.
   E o blur cai de 28 para 22px: acima disso o ganho visual é nulo e o
   custo cresce com o quadrado do raio. */
.mat__fundo{position:absolute;top:50%;left:50%;min-width:112%;min-height:112%;
  transform:translate(-50%,-50%) scale(1.08);object-fit:cover;
  filter:blur(0) brightness(.55);opacity:.9;
  transition:filter .5s ease .15s}
body.pronto .mat__fundo{filter:blur(22px) saturate(1.15) brightness(.65)}

/* Foto nítida por cima. Sendo grande, preenche a tela e o fundo nem aparece. */
.mat__foto{position:absolute;top:50%;left:50%;width:100%;height:100%;
  transform:translate(-50%,-50%);object-fit:cover;object-position:center}

/* Foto pequena: em vez de esticar, mostra no tamanho que aguenta, com o
   fundo desfocado preenchendo o resto. É o recurso que serviço de streaming
   usa em capa antiga, e é o que separa "borrado" de "intencional". */
.matéria.pequena .mat__foto{width:auto;height:auto;max-width:56vw;max-height:50vh;
  top:31%;object-fit:contain;border-radius:6px;
  box-shadow:0 24px 70px rgba(0,0,0,.6)}
.matéria.pequena .mat__txt{bottom:4vw}
.matéria.pequena .mat__tit{font-size:4.2vw;max-width:30ch}
.matéria.pequena .mat__res{font-size:1.9vw}

/* ── Modo "a arte já traz o título" ───────────────────────────
   Fica DEPOIS das regras de .pequena de propósito: as duas têm a mesma
   especificidade, e em empate vence a última. Sem esta ordem, uma arte
   detectada como pequena voltava a ser cortada.

   contain, não cover: a manchete costuma estar perto da borda, que é
   exatamente o que o cover corta. O fundo desfocado preenche o resto. */
.matéria.soimg .mat__foto{width:100%;height:100%;max-width:none;max-height:none;
  top:50%;object-fit:contain;border-radius:0;box-shadow:none}
.matéria.soimg .veu{background:linear-gradient(180deg,
  rgba(12,14,28,.30) 0%,transparent 20%,transparent 76%,rgba(12,14,28,.55) 100%)}
.matéria:not([data-img]){background:
  radial-gradient(1500px 780px at 80% -14%,#2E3478 0,transparent 62%),
  radial-gradient(900px 620px at -8% 110%,#2A2313 0,transparent 58%),#0C0E1C}
.matéria:not([data-img]) .veu{display:none}
.matéria:not([data-img]) .mat__txt{top:50%;bottom:auto;transform:translateY(-50%)}
.matéria:not([data-img]) .mat__tit{font-size:6vw;max-width:20ch}
.matéria.on{opacity:1}
.veu{position:absolute;top:0;left:0;right:0;bottom:0;z-index:1;
  background:linear-gradient(180deg,rgba(12,14,28,.72) 0%,rgba(12,14,28,.30) 34%,
             rgba(12,14,28,.86) 68%,rgba(12,14,28,.97) 100%)}
.mat__txt{z-index:2}
.mat__txt{position:absolute;left:5vw;right:5vw;bottom:6vw}
.mat__topo{font-size:1.5vw;letter-spacing:.2em;text-transform:uppercase;color:#C08A28;
  font-weight:700;margin-bottom:1.6vw}
.mat__topo span{color:#9EA2C0;font-weight:400;letter-spacing:.1em;margin-left:1.2vw}
/* O tamanho vem do script, que MEDE a manchete. Fixo em 5.2vw, uma
   manchete de 15 palavras ocupava a tela inteira e engolia a foto —
   e a foto é metade da razão de a peça existir. */
.mat__tit{font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
  font-size:var(--tit, 4.4vw);font-weight:400;line-height:1.1;letter-spacing:-.015em;
  margin:0 0 1.6vw;max-width:20ch;
  text-shadow:0 2px 18px rgba(0,0,0,.6)}
.mat__res{font-size:var(--res, 1.9vw);line-height:1.45;color:#D8DAE8;max-width:44ch;
  text-shadow:0 1px 12px rgba(0,0,0,.6);
  /* Teto de 3 linhas: acima disso vira leitura, não sinalização. */
  display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.passos{position:fixed;right:5vw;bottom:6vw;display:flex;gap:.8vw;z-index:3}
.passos i{width:1.1vw;height:.28vw;background:rgba(236,219,174,.28);display:block;
  transition:background .4s}
.passos i.on{background:#C08A28}
.matéria .marca{z-index:2}
@media (prefers-reduced-motion:reduce){.matéria{transition:none}}

/* ── Instagram ────────────────────────────────────────────────
   A MESMA peça serve à coluna de 30% e à tela cheia. Container queries
   seriam o certo, mas TV de 2017 não tem: então uso proporção de tela.
   Coluna estreita empilha; tela larga vira faixa de três. */
.ig2{position:fixed;inset:0;opacity:0;overflow:hidden;background:#0C0E1C;
  transition:opacity .8s ease;pointer-events:none}
.ig2.on{opacity:1}
.ig2__fundo{position:absolute;top:50%;left:50%;min-width:114%;min-height:114%;
  transform:translate(-50%,-50%) scale(1.1);object-fit:cover;
  filter:blur(0) brightness(.5);transition:filter .5s ease .15s}
body.pronto .ig2__fundo{filter:blur(22px) saturate(1.2) brightness(.6)}
.ig2__foto{position:absolute;top:50%;left:50%;width:100%;height:100%;
  transform:translate(-50%,-50%);object-fit:cover}
/* Post quadrado ou vertical: mostra inteiro, deslocado, com o texto na
   coluna livre. Esticar quadrado em 16:9 corta metade da arte, que e
   justamente onde o marketing poe a informacao. */
.ig2.vertical .ig2__foto{width:auto;height:84vh;left:31%;object-fit:contain;
  border-radius:8px;box-shadow:0 28px 80px rgba(0,0,0,.6)}
.ig2.vertical .ig2__txt{left:auto;right:4vw;width:33vw;bottom:auto;top:50%;
  transform:translateY(-50%)}
.ig2.vertical .ig2__leg{font-size:2.1vw;max-width:100%}
.ig2.semfoto .ig2__foto,.ig2.semfoto .ig2__fundo{display:none}
.ig2__veu{position:absolute;inset:0;z-index:1;
  background:linear-gradient(180deg,rgba(12,14,28,.68) 0%,rgba(12,14,28,.22) 32%,
             rgba(12,14,28,.84) 70%,rgba(12,14,28,.97) 100%)}
.ig2__txt{position:absolute;left:5vw;right:5vw;bottom:6vw;z-index:2}
.ig2__topo{font-size:1.6vw;letter-spacing:.16em;text-transform:uppercase;
  color:#ECDBAE;font-weight:600;margin-bottom:1.5vw;display:flex;
  align-items:center;gap:1.2vw;flex-wrap:wrap}
.ig2__selo{background:linear-gradient(135deg,#C08A28,#D9A83F);color:#231502;
  padding:.4vw 1vw;border-radius:3px;font-weight:700;letter-spacing:.12em}
.ig2__topo i{font-style:normal;color:#9EA2C0;font-weight:400;letter-spacing:.08em}
.ig2__leg{font-size:2.9vw;line-height:1.32;color:#F1EFE7;max-width:34ch;margin:0;
  text-shadow:0 2px 16px rgba(0,0,0,.6)}
.ig2--convite{background:
  radial-gradient(1500px 800px at 78% -14%,#2E3478 0,transparent 60%),
  radial-gradient(1000px 640px at -8% 110%,#3A2A10 0,transparent 56%),#0C0E1C}
.ig2__conv{position:absolute;inset:0;display:flex;align-items:center;
  justify-content:center;gap:5vw;padding:0 6vw}
.ig2__qr{width:30vh;height:30vh;border-radius:8px;flex:0 0 auto;
  box-shadow:0 20px 60px rgba(0,0,0,.5)}
.ig2__sup{font-size:2.2vw;color:#9EA2C0;margin:0 0 1vw;letter-spacing:.1em}
.ig2__arroba{font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
  font-size:5.2vw;color:#ECDBAE;margin:0;letter-spacing:-.015em;line-height:1.05}
.ig2__aponte{margin-top:2vw;font-size:1.5vw;color:#6A6F98;letter-spacing:.14em;
  text-transform:uppercase}
@media (max-aspect-ratio:1/1){
  .ig2__conv{flex-direction:column;text-align:center;gap:4vh}
  .ig2.vertical .ig2__foto{height:50vh;left:50%}
  .ig2.vertical .ig2__txt{position:absolute;left:5vw;right:5vw;width:auto;
    top:auto;bottom:6vh;transform:none}
  .ig2__leg{font-size:2.6vh}
  .ig2__topo{font-size:1.5vh}
  .ig2__sup{font-size:2.4vh}
  .ig2__arroba{font-size:5vh}
  .ig2__aponte{font-size:1.5vh}
}

/* ── Política da Qualidade ────────────────────────────────────
   Mesma gramática da peça de aniversariantes, com o gesto invertido: lá o
   movimento é festivo e rápido; aqui é lento e contínuo. Peça institucional
   precisa parecer sólida. */
.qa{position:fixed;inset:0;z-index:2;display:none;flex-direction:column;
  align-items:center;justify-content:center;text-align:center;
  padding:10vh 15vw 10vh 11vw;box-sizing:border-box}
.qa.on{display:flex;animation:qaEntra .9s cubic-bezier(.2,.8,.3,1) both}
@keyframes qaEntra{from{opacity:0;transform:translateY(1.6vh)}to{opacity:1;transform:none}}

/* Ondas: três faixas largas girando devagar. Sugerem movimento sem chamar
   atenção para si — o contrário dos balões. */
.ondas{position:fixed;inset:0;overflow:hidden;pointer-events:none;z-index:1}
.onda{position:absolute;left:-30%;width:160%;height:60vh;border-radius:44%;
  opacity:.10;will-change:transform}
.o1{bottom:-34vh;background:#3B4192;animation:gira 26s linear infinite}
.o2{bottom:-38vh;background:#C08A28;animation:gira 34s linear infinite reverse;opacity:.08}
.o3{bottom:-42vh;background:#2A2F6C;animation:gira 44s linear infinite;opacity:.09}
@keyframes gira{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}

/* Abertura */
.qa__sup{font-size:1.8vw;letter-spacing:.32em;text-transform:uppercase;color:#C08A28;
  font-weight:700;margin-bottom:2.6vw;animation:qaSurge .8s .2s both}
.qa__marca{font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
  font-size:7.6vw;font-weight:400;line-height:1.06;margin:0;letter-spacing:-.02em;
  animation:qaSurge .9s .38s both}
.qa__selo{margin-top:3vw;font-size:1.6vw;letter-spacing:.4em;color:#6A6F98;
  border:1px solid rgba(236,219,174,.28);padding:.9vw 2.4vw;border-radius:2px;
  animation:qaSurge .9s .6s both}
@keyframes qaSurge{from{opacity:0;transform:translateY(1.4vw)}to{opacity:1;transform:none}}

/* Rótulo comum a todas as telas */
/* MISSÃO, VISÃO, VALORES em dourado.
   Estava em 1.5vw, o mesmo tamanho dos rótulos secundários — e a 3 metros
   de distância virava um detalhe. Ele encabeça a tela: precisa ser lido
   antes do texto, não junto com o rodapé. */
.qa__rot{font-size:2.1vw;letter-spacing:.28em;text-transform:uppercase;color:#C08A28;
  font-weight:700;margin-bottom:2.4vw}

/* A política: aspas grandes, como citação — é a frase que a empresa assina */
.qa__frase{font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
  font-size:4.4vw;line-height:1.28;font-weight:400;margin:0;max-width:24ch;
  color:#F1EFE7;position:relative;quotes:"\201C" "\201D"}
.qa__frase::before{content:open-quote;color:#C08A28;font-size:1.3em;line-height:0;
  vertical-align:-.28em;margin-right:.1em}
.qa__frase::after{content:close-quote;color:#C08A28;font-size:1.3em;line-height:0;
  vertical-align:-.28em;margin-left:.05em}
.qa__rev{margin-top:3.4vw;font-size:1.2vw;color:#6A6F98;letter-spacing:.22em;
  text-transform:uppercase}

/* Missão e visão: parágrafo, sem aspas */
/* O texto em si. 30ch de largura mantém a linha curta o bastante para
   ler de longe — aumentar a fonte sem isso só faria a frase atravessar a
   tela inteira. */
.qa__corpo{font-size:3.6vw;line-height:1.4;color:#F1EFE7;max-width:28ch;
  margin:0;font-weight:300}

/* Valores: grade que entra em cascata */
.qa__grade{display:flex;flex-wrap:wrap;justify-content:center;gap:1.4vw 2.6vw;
  max-width:80vw}
.qa__valor{font-size:2.9vw;font-weight:300;color:#F1EFE7;
  padding:.7vw 1.8vw;border:1px solid rgba(236,219,174,.20);border-radius:3px;
  background:rgba(236,219,174,.045);animation:qaSurge .7s both}

@media (max-aspect-ratio:1/1){
  .qa{padding:8vh 8vw}
  .qa__marca{font-size:9vh}.qa__frase{font-size:5vh}.qa__corpo{font-size:4.2vh}
  .qa__valor{font-size:3vh}.qa__rot{font-size:2.4vh}.qa__sup{font-size:1.7vh}
  .qa__selo{font-size:1.6vh}.qa__rev{font-size:1.4vh}
}
@media (prefers-reduced-motion:reduce){
  .onda{animation:none}.qa.on,.qa__sup,.qa__marca,.qa__selo,.qa__valor{animation:none}
}

/* ── Redes sociais ────────────────────────────────────────────
   Um cartão por rede, cada um com QR próprio. O QR é o ponto da peça:
   numa sala de espera a pessoa está parada com o celular na mão, e
   digitar @perfil é fricção suficiente para ela desistir. */
/* 11vh em cima e embaixo: a chamada do topo e o endereço do site estavam
   passando da margem de segurança, e é justamente o que a TV corta. */
.rd{position:fixed;inset:0;z-index:2;display:flex;flex-direction:column;
  align-items:center;justify-content:center;text-align:center;
  padding:11vh 12vw 11vh 10vw;box-sizing:border-box}
.rd__sup{font-size:1.7vw;letter-spacing:.3em;text-transform:uppercase;color:#C08A28;
  font-weight:700;margin-bottom:1.4vw;animation:qaSurge .8s .1s both}
.rd__tit{font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
  font-size:4.8vw;font-weight:400;margin:0 0 2.8vw;letter-spacing:-.02em;
  animation:qaSurge .9s .22s both}

.rd__grade{display:flex;justify-content:center;align-items:stretch;gap:2.4vw;
  width:100%;max-width:100%}
.rd__cartao{flex:1;max-width:22vw;display:flex;flex-direction:column;align-items:center;
  gap:.8vw;padding:1.5vw 1.2vw;border:1px solid rgba(236,219,174,.16);border-radius:5px;
  background:rgba(236,219,174,.04);animation:qaSurge .8s both}
/* Menos redes, cartões maiores: com duas, metade da tela ficaria vazia. */
.rd--1 .rd__cartao{max-width:34vw}
.rd--2 .rd__cartao{max-width:28vw}
.rd--3 .rd__cartao{max-width:24vw}

.rd__qr{width:100%;max-width:12vw;aspect-ratio:1;border-radius:4px;
  box-shadow:0 10px 34px rgba(0,0,0,.4)}
.rd__icone{display:block;width:2.8vw;height:2.8vw;color:#C08A28;margin-top:.4vw}
.rd__icone svg{width:100%;height:100%}
.rd__rede{font-size:1.9vw;font-weight:600;color:#F1EFE7;letter-spacing:.02em}
.rd__perfil{font-size:1.25vw;color:#9EA2C0;word-break:break-all;line-height:1.3}

.rd__aponte{margin-top:1.8vw;font-size:1.3vw;letter-spacing:.16em;text-transform:uppercase;
  color:#6A6F98;animation:qaSurge .9s .9s both}
.rd__site{margin-top:.8vw;font-size:1.4vw;color:#C08A28;letter-spacing:.06em;
  animation:qaSurge .9s 1s both}

/* Tela em pé (zona lateral): empilha e diminui o QR. */
/* Coluna estreita: empilha em linhas, com o QR à esquerda e o nome ao
   lado. Números menores que na tela cheia porque aqui a altura é o que
   falta, não a largura. */
@media (max-aspect-ratio:1/1){
  .rd{padding:11vh 7vw 11vh 7vw}
  .rd__grade{flex-direction:column;gap:1.2vh;width:100%}
  .rd__cartao{max-width:none;flex-direction:row;align-items:center;
    justify-content:flex-start;gap:1.8vh;padding:1.2vh 1.4vh;text-align:left}
  .rd--1 .rd__cartao,.rd--2 .rd__cartao,.rd--3 .rd__cartao{max-width:none}
  .rd__qr{max-width:9vh;flex:0 0 auto}
  .rd__icone{display:none}
  .rd__tit{font-size:3.6vh;margin-bottom:1.6vh}
  .rd__sup{font-size:1.3vh;margin-bottom:.8vh}
  .rd__rede{font-size:2vh}.rd__perfil{font-size:1.4vh}
  .rd__aponte{font-size:1.2vh;margin-top:1.6vh}
  .rd__site{font-size:1.4vh;margin-top:.6vh}
}

/* ── Convite para o grupo ─────────────────────────────────────
   Duas colunas: o texto convence à esquerda, o QR age à direita. Ler e
   apontar são gestos diferentes e merecem espaços diferentes. */
.gp{position:fixed;inset:0;z-index:2;display:flex;align-items:center;
  justify-content:center;gap:6vw;padding:11vh 12vw 11vh 10vw;box-sizing:border-box}
.gp__esq{flex:1;max-width:44vw;text-align:left}
.gp__dir{flex:0 0 auto;display:flex;flex-direction:column;align-items:center;gap:1.8vw}

.gp__sup{font-size:1.7vw;letter-spacing:.28em;text-transform:uppercase;color:#C08A28;
  font-weight:700;margin-bottom:1.4vw;animation:qaSurge .8s .12s both}
.gp__tit{font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
  font-size:5.6vw;font-weight:400;line-height:1.06;margin:0;letter-spacing:-.02em;
  animation:qaSurge .9s .28s both}

.gp__lista{list-style:none;margin:3vw 0 0;padding:0;display:flex;
  flex-direction:column;gap:1.1vw}
.gp__lista li{font-size:1.9vw;color:#F1EFE7;font-weight:300;display:flex;
  align-items:center;gap:1.1vw;animation:qaSurge .7s both}
/* Marcador em losango dourado, desenhado em CSS: não depende de fonte de
   ícone nem de imagem que possa faltar. */
.gp__lista li::before{content:"";flex:0 0 auto;width:.7vw;height:.7vw;
  background:#C08A28;transform:rotate(45deg)}

/* Anéis pulsando para fora do QR. Dois, com atraso entre eles, num ciclo
   longo: pulso rápido vira ruído e cansa em parede que fica horas no ar. */
.gp__alvo{position:relative;display:flex;align-items:center;justify-content:center}
.gp__anel{position:absolute;inset:0;border:2px solid #C08A28;border-radius:12px;
  opacity:0;animation:pulsa 3.6s cubic-bezier(.2,.7,.4,1) infinite}
.gp__anel.a2{animation-delay:1.8s}
@keyframes pulsa{
  0%   { transform:scale(1);    opacity:.55; }
  70%  { transform:scale(1.28); opacity:0; }
  100% { transform:scale(1.28); opacity:0; }
}
.gp__qr{position:relative;z-index:1;width:26vw;max-width:340px;aspect-ratio:1;
  border-radius:8px;box-shadow:0 18px 60px rgba(0,0,0,.5);
  animation:qaSurge .9s .45s both}
/* Limitado à largura do QR: solto, o texto vazava para fora da coluna e
   passava da margem de segurança à direita. */
.gp__rodape{font-size:1.2vw;letter-spacing:.12em;text-transform:uppercase;
  color:#6A6F98;text-align:center;max-width:26vw;margin:0 auto;line-height:1.4;
  animation:qaSurge .9s .8s both}

/* Coluna estreita ou tela em pé: empilha, QR embaixo do texto. */
@media (max-aspect-ratio:1/1){
  .gp{flex-direction:column;gap:2.6vh;padding:12vh 11vw;justify-content:center}
  .gp__esq{max-width:none;text-align:center}
  .gp__tit{font-size:4.4vh}.gp__sup{font-size:1.4vh;margin-bottom:1vh}
  .gp__lista{margin-top:2vh;gap:.9vh;align-items:center}
  .gp__lista li{font-size:1.8vh;gap:1.1vh}
  .gp__lista li::before{width:.7vh;height:.7vh}
  .gp__qr{width:26vh;max-width:none}
  .gp__rodape{font-size:1.2vh;max-width:none}
}
@media (prefers-reduced-motion:reduce){ .gp__anel{animation:none;opacity:.3} }

/* ── Cotação ──────────────────────────────────────────────────
   Um número grande e a data. Nada mais: quem passa por um terminal olha
   isso por dois segundos, e qualquer coisa a mais compete com o número. */
.ct{position:fixed;inset:0;z-index:2;display:flex;flex-direction:column;
  align-items:center;justify-content:center;text-align:center;
  padding:11vh 13vw;box-sizing:border-box}
.ct__sup{font-size:1.9vw;letter-spacing:.3em;text-transform:uppercase;color:#C08A28;
  font-weight:700;margin-bottom:2vw;animation:qaSurge .8s .1s both}
.ct__valor{font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
  font-size:11vw;line-height:1;margin:0;letter-spacing:-.03em;color:#F1EFE7;
  animation:qaSurge .9s .26s both}
.ct__cifra{font-size:.42em;color:#9EA2C0;margin-right:.5vw;vertical-align:.32em;
  letter-spacing:0}
.ct__var{margin-top:2.4vw;font-size:2.6vw;font-weight:600;letter-spacing:.02em;
  animation:qaSurge .9s .44s both}
.ct__var.sobe{color:#E0576E}   /* dólar subindo é notícia ruim para quem compra */
.ct__var.cai{color:#57C98B}
.ct__var i{display:block;font-style:normal;font-size:.46em;color:#6A6F98;
  font-weight:400;margin-top:.7vw;letter-spacing:.08em;text-transform:uppercase}
.ct__quando{margin-top:3vw;font-size:1.6vw;color:#9EA2C0;animation:qaSurge .9s .6s both}
.ct__fonte{margin-top:.9vw;font-size:1.2vw;color:#6A6F98;letter-spacing:.14em;
  text-transform:uppercase;animation:qaSurge .9s .72s both}
.ct__indisp{font-size:4vw;color:#6A6F98;font-weight:300;margin:2vw 0}
@media (max-aspect-ratio:1/1){
  .ct{padding:9vh 7vw}
  .ct__valor{font-size:10vh}.ct__sup{font-size:1.7vh}.ct__var{font-size:2.6vh}
  .ct__quando{font-size:1.6vh}.ct__fonte{font-size:1.2vh}.ct__indisp{font-size:4vh}
}

/* Marca de conteúdo antigo. Discreta de propósito: a peça continua
   cumprindo o papel, e quem passa não precisa saber de problema de rede.
   Mas quem OPERA precisa — e uma parede que mostra notícia de ontem sem
   avisar é pior que uma que avisa. */
.semrede{position:fixed;top:2.4vw;left:5vw;z-index:4;
  font-size:1.1vw;letter-spacing:.18em;text-transform:uppercase;
  color:#9EA2C0;background:rgba(12,14,28,.62);
  border:1px solid rgba(158,162,192,.28);border-radius:3px;
  padding:.4vw 1vw}
@media (max-aspect-ratio:1/1){ .semrede{font-size:1.2vh;padding:.5vh 1vh;top:2vh;left:4vw} }

/* ── Agenda / calendário ──────────────────────────────────────
   O exemplo de referência usa neon sobre preto. Aqui vai a paleta da
   Redentor pelo mesmo motivo de sempre: a peça divide a parede com as
   outras, e cada uma com identidade própria vira colcha de retalhos.
   A estrutura é a mesma — grade à esquerda, lista à direita. */
.ag{position:fixed;inset:0;z-index:2;display:flex;flex-direction:column;
  padding:5vh 4vw;box-sizing:border-box;gap:2vh}
.ag__topo{display:flex;align-items:flex-start;gap:2vw;flex:0 0 auto}
.ag__tit{font-family:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,serif;
  font-size:3.4vw;font-weight:400;margin:0;letter-spacing:-.02em;line-height:1.05}
.ag__mes{font-size:1.7vw;color:#C08A28;font-weight:700;letter-spacing:.18em;
  text-transform:uppercase;margin-top:.4vw}
.ag__frase{flex:1;font-size:1.15vw;color:#9EA2C0;line-height:1.5;max-width:30ch;
  border-left:2px solid #C08A28;padding-left:1.2vw;margin-top:.6vw;font-style:italic}
.ag__logo{height:4vw;width:auto;margin-left:auto}

.ag__corpo{flex:1;display:flex;gap:2vw;min-height:0}

/* Grade: sete colunas fixas. Calendário que muda de forma conforme o mês
   obriga a reaprender a leitura toda vez. */
.ag__grade{flex:1;display:grid;grid-template-columns:repeat(7,1fr);
  grid-auto-rows:minmax(0,1fr);gap:.5vw;min-height:0}
.ag__dia-sem{font-size:1.1vw;letter-spacing:.16em;text-transform:uppercase;
  color:#6A6F98;font-weight:700;text-align:center;padding-bottom:.4vw;
  align-self:center}
.ag__dia-sem.fds{color:#C08A28}
.ag__vazio{border-radius:4px;background:rgba(236,219,174,.02)}

.ag__dia{position:relative;border:1px solid rgba(236,219,174,.10);border-radius:4px;
  padding:.5vw .6vw;display:flex;flex-direction:column;gap:.2vw;overflow:hidden;
  background:rgba(236,219,174,.03)}
.ag__dia.fds{background:rgba(12,14,28,.5)}
.ag__n{font-size:1.5vw;font-weight:300;color:#D8DAE8;line-height:1}
/* Hoje: contorno dourado. É a primeira coisa que se procura num calendário. */
.ag__dia.hoje{border-color:#C08A28;border-width:2px;background:rgba(192,138,40,.10)}
.ag__dia.hoje .ag__n{color:#ECDBAE;font-weight:600}

/* Dia com compromisso: cor cheia, número maior e o nome embaixo. */
.ag__dia.tem{border-width:0}
.ag__dia.tem .ag__n{font-size:1.9vw;font-weight:600;color:#fff}
.ag__ev{font-size:.72vw;line-height:1.2;color:rgba(255,255,255,.92);font-weight:600;
  text-transform:uppercase;letter-spacing:.04em;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}

/* Cinco cores, para a contabilidade separar tipos de obrigação. */
.c-azul   { background:linear-gradient(150deg,#3B4192,#2A2F6C) }
.c-verde  { background:linear-gradient(150deg,#2F8F63,#1F6B48) }
.c-roxo   { background:linear-gradient(150deg,#6B4A9E,#4A3270) }
.c-laranja{ background:linear-gradient(150deg,#C08A28,#8A6015) }
.c-vermelho{background:linear-gradient(150deg,#B03A50,#7E2537) }

/* Lista lateral */
.ag__lado{flex:0 0 26vw;display:flex;flex-direction:column;gap:.8vh;min-height:0}
.ag__lado-tit{font-size:1.1vw;letter-spacing:.2em;text-transform:uppercase;
  color:#C08A28;font-weight:700;margin-bottom:.4vh}
.ag__card{border-radius:4px;padding:.9vh 1vw;display:flex;flex-direction:column;
  gap:.15vh;animation:qaSurge .7s both;flex:0 1 auto}
.ag__card.passou{opacity:.42}   /* já venceu: continua visível, sem competir */
.ag__data{font-size:1.5vw;font-weight:700;color:#fff;line-height:1}
.ag__nome{font-size:.95vw;font-weight:600;color:rgba(255,255,255,.95);
  text-transform:uppercase;letter-spacing:.04em;line-height:1.25}
.ag__det{font-size:.8vw;color:rgba(255,255,255,.72);line-height:1.3;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.ag__nada{font-size:1.1vw;color:#6A6F98;line-height:1.6}

.ag__rodape{flex:0 0 auto;text-align:center;font-size:1vw;color:#C08A28;
  letter-spacing:.2em;text-transform:uppercase;font-weight:600;
  border-top:1px solid rgba(236,219,174,.14);padding-top:1.4vh}

/* Tela em pé: a lista vai para baixo da grade. */
@media (max-aspect-ratio:1/1){
  .ag{padding:4vh 5vw}
  .ag__corpo{flex-direction:column}
  .ag__lado{flex:0 0 auto;flex-direction:row;flex-wrap:wrap;gap:1vh}
  .ag__card{flex:1 1 30%}
  .ag__tit{font-size:4vh}.ag__mes{font-size:1.8vh}.ag__frase{display:none}
  .ag__n{font-size:2vh}.ag__dia.tem .ag__n{font-size:2.4vh}
  .ag__ev{font-size:1vh}.ag__dia-sem{font-size:1.3vh}
  .ag__data{font-size:2vh}.ag__nome{font-size:1.3vh}.ag__det{font-size:1.1vh}
  .ag__lado-tit{font-size:1.3vh}.ag__rodape{font-size:1.2vh}
}

.erro{font-size:3vw;color:#9EA2C0;text-align:center}
@media (prefers-reduced-motion:reduce){.sep{transition:none}}
</style>
