<script>
(function(){
  /* A abertura roda SEMPRE que a peça entra no ar. Eu tinha limitado a uma
     vez por dia achando que cansaria, mas o item aparece poucas vezes por
     hora e a abertura é justamente o que faz alguém olhar para a tela: sem
     ela, os nomes entram sem aviso e passam despercebidos. */
  var ABERT = 6000;
  var jaViu = false;

  var abertura = document.getElementById('abertura');
  var lista = document.getElementById('listaNiver');
  var pgs = lista.querySelectorAll('.pgNiver');
  var pontos = lista.querySelectorAll('.passos i');

  function mostrarLista(){
    abertura.className = 'festa saiu';
    lista.hidden = false;
    // Mede depois de visível: elemento escondido tem largura zero.
    setTimeout(function(){
      lista.className = 'tela hoje entrou';
      for(var i = 0; i < pgs.length; i++) ajustar(pgs[i]);
    }, 30);
    girarPaginas();
  }

  /* AJUSTE AO ESPAÇO REAL.
     Uma faixa fixa de tamanho por quantidade não resolve: "Ana Lima" e
     "Elizete Kuckel de Oliveira Palisser" têm contagens muito diferentes,
     e foi assim que o nome vazou por cima da logo. Aqui o script mede a
     caixa disponível e diminui até caber, nome por nome. */
  function ajustar(pagina){
    var caixa = pagina.querySelector('.nivHoje');
    if(!caixa) return;
    var nomes = caixa.querySelectorAll('.nh');
    var alturaMax = window.innerHeight * 0.62;
    var larguraMax = caixa.clientWidth;

    // Ponto de partida conforme quantos nomes, depois encolhe se precisar.
    /* Uns 18% menor que antes. O ajuste automático já impedia o estouro,
       mas encher a tela de borda a borda cansa: sobrar ar em volta faz o
       nome ser lido mais rápido, não mais devagar. */
    var base = nomes.length === 1 ? 7.4 : (nomes.length <= 2 ? 5.8
             : (nomes.length <= 4 ? 4.4 : 3.2));

    for(var i = 0; i < nomes.length; i++){
      var el = nomes[i], tam = base, voltas = 0;
      el.style.setProperty('--tam', tam + 'vw');

      /* Medir o ELEMENTO não serve: ele ocupa a largura toda, então
         scrollWidth nunca passa do limite mesmo com o texto vazando. O que
         precisa ser medido é a LINHA de texto — e para isso existe
         getClientRects, que devolve uma caixa por linha renderizada.
         Foi exatamente esse detalhe que deixou o nome passar por cima da
         logo na primeira tentativa. */
      function maiorLinha(no){
        var faixa = document.createRange();
        faixa.selectNodeContents(no);
        var caixas = faixa.getClientRects(), m = 0;
        for(var k = 0; k < caixas.length; k++) m = Math.max(m, caixas[k].width);
        return m;
      }

      // Só o nome, sem o cargo: o cargo já é bem menor.
      var soNome = el.firstChild;
      // Piso de 2.2vw: abaixo disso não se lê de longe, e aí é melhor
      // deixar quebrar em duas linhas do que virar letra miúda.
      while(soNome && maiorLinha(soNome) > larguraMax - 2 && tam > 2.2 && voltas < 40){
        tam -= 0.2;
        el.style.setProperty('--tam', tam + 'vw');
        voltas++;
      }
    }

    /* Altura: um nome que quebrou em duas linhas empurra o conjunto para
       fora da tela. Reduzo TODOS junto, mantendo a proporção, até caber.
       Comparo com a altura da ÁREA ÚTIL, não com a da caixa — a caixa
       cresce com o conteúdo e nunca acusaria estouro. */
    var util = pagina.parentNode ? pagina.parentNode.clientHeight : alturaMax;
    var teto = Math.min(alturaMax, util) - 4;
    var voltas2 = 0;
    while(caixa.getBoundingClientRect().height > teto && voltas2 < 40){
      var mudou = false;
      for(var j = 0; j < nomes.length; j++){
        var atual = parseFloat(nomes[j].style.getPropertyValue('--tam')) || base;
        if(atual <= 2.2) continue;
        nomes[j].style.setProperty('--tam', (atual - 0.25) + 'vw');
        mudou = true;
      }
      if(!mudou) break;
      voltas2++;
    }
  }

  function girarPaginas(){
    if(pgs.length < 2) return;
    var i = 0;
    setInterval(function(){
      pgs[i].className = 'pgNiver';
      if(pontos[i]) pontos[i].className = '';
      i = (i + 1) % pgs.length;
      pgs[i].className = 'pgNiver on';
      if(pontos[i]) pontos[i].className = 'on';
    }, 9000);
  }

  if(jaViu){
    abertura.style.display = 'none';
    mostrarLista();
  } else {
    setTimeout(mostrarLista, ABERT);
  }

  /* Vira o dia: recarrega para o servidor decidir de novo. Sem isto, uma TV
     ligada direto continuaria mostrando a lista de ontem depois da meia-noite,
     até a próxima sincronização. */
  var agora = new Date();
  var meia = new Date(agora.getFullYear(), agora.getMonth(), agora.getDate() + 1, 0, 0, 30);
  setTimeout(function(){ location.reload(); }, Math.min(meia - agora, 1800000));
})();
</script>

