<script>
(function(){
  /* Cada tela tem o próprio tempo, no data-t: a política é a mais
     importante e fica mais; missão e visão são parágrafos e pedem menos.
     Tempo igual para tudo faria a frase principal passar rápido demais. */
  var TELAS = document.querySelectorAll('.qa');
  var PASSOS = document.getElementById('qaPassos');

  var pontos = '';
  for(var i = 0; i < TELAS.length; i++) pontos += '<i' + (i === 0 ? ' class="on"' : '') + '></i>';
  PASSOS.innerHTML = TELAS.length > 1 ? pontos : '';
  var PT = PASSOS.querySelectorAll('i');

  /* Ajusta o texto ao espaço, como na peça de aniversariantes: missão e
     visão têm comprimentos bem diferentes, e tamanho fixo faria uma sobrar
     e a outra estourar. */
  function ajustar(sec){
    var alvo = sec.querySelector('.qa__frase, .qa__corpo');
    if(!alvo) return;
    var caixa = sec.getBoundingClientRect();
    var teto = caixa.height * 0.62;
    var tam = parseFloat(getComputedStyle(alvo).fontSize) / window.innerWidth * 100;
    var voltas = 0;
    while(alvo.scrollHeight > teto && tam > 1.6 && voltas < 40){
      tam -= 0.12;
      alvo.style.fontSize = tam + 'vw';
      voltas++;
    }
  }

  if(TELAS.length > 1){
    var n = 0;
    (function girar(){
      var espera = parseInt(TELAS[n].getAttribute('data-t'), 10) || 12000;
      setTimeout(function(){
        TELAS[n].classList.remove('on');
        if(PT[n]) PT[n].className = '';
        n = (n + 1) % TELAS.length;
        TELAS[n].classList.add('on');
        if(PT[n]) PT[n].className = 'on';
        ajustar(TELAS[n]);
        girar();
      }, espera);
    })();
  }

  setTimeout(function(){ for(var i = 0; i < TELAS.length; i++) ajustar(TELAS[i]); }, 60);
  setTimeout(function(){ location.reload(); }, 3600000);
})();
</script>

