<script>
(function(){
  /* Sequência: post, post, convite. O convite fica menos tempo — é fecho,
     não conteúdo, e quem já viu o QR não precisa de meio minuto de novo. */
  var TELAS = document.querySelectorAll('.ig2');
  var PONTOS = document.querySelectorAll('#igPassos i');
  var T_POST = 14000, T_CONV = 9000;

  function medir(art){
    var foto = art.querySelector('.ig2__foto');
    if(!foto) return;
    function ver(){
      if(!foto.naturalWidth) return;
      // Quadrado ou vertical não pode ser esticado: mostra inteiro.
      if(foto.naturalHeight >= foto.naturalWidth * 0.95) art.className += ' vertical';
    }
    if(foto.complete) ver(); else foto.addEventListener('load', ver);
    foto.addEventListener('error', function(){ art.className += ' semfoto'; });
  }
  for(var i = 0; i < TELAS.length; i++) medir(TELAS[i]);

  if(TELAS.length > 1){
    var n = 0;
    (function girar(){
      var eConvite = TELAS[n].className.indexOf('convite') > -1;
      setTimeout(function(){
        TELAS[n].className = TELAS[n].className.replace(' on', '');
        if(PONTOS[n]) PONTOS[n].className = '';
        n = (n + 1) % TELAS.length;
        TELAS[n].className += ' on';
        if(PONTOS[n]) PONTOS[n].className = 'on';
        girar();
      }, eConvite ? T_CONV : T_POST);
    })();
  }

  /* Busca de 5 em 5 min. Só recarrega se as fotos mudaram: recarregar sem
     motivo pisca a tela e reinicia a sequência do zero. */
  var MIN = 300000, falhas = 0, t = null;
  var atual = <?php echo json_encode(array_map(function($p){ return $p['img']; }, $doIg)); ?>.join('|');

  function agendar(ms){ clearTimeout(t); t = setTimeout(buscar, ms); }

  function buscar(){
    var x = new XMLHttpRequest();
    x.open('GET', 'tvindoor.php?action=insta_publico&t=' + Date.now(), true);
    x.timeout = 15000;
    x.onload = function(){
      var d = null;
      try { d = JSON.parse(x.responseText); } catch(e){}
      if(!d || !d.ok || !d.posts){ falhar(); return; }
      falhas = 0;
      var nova = d.posts.slice(0, 2).map(function(p){ return p.img; }).join('|');
      if(nova !== atual) location.reload();
      else agendar(MIN);
    };
    x.onerror = x.ontimeout = falhar;
    x.send();
  }

  /* Rede caída: NÃO limpa a tela. O que está no ar continua, e a espera
     dobra a cada erro até 30 min. */
  function falhar(){
    falhas++;
    agendar(Math.min(1800000, MIN * Math.pow(2, Math.min(falhas, 3))));
  }
  agendar(MIN);
})();
</script>

