<script>
(function(){
  /* Uma manchete por vez. Lista de títulos numa parede ninguém lê; uma foto
     grande com uma frase, sim. */
  var mats = document.querySelectorAll('.matéria');
  var pontos = document.querySelectorAll('.passos i');

  /* CONTINUA DE ONDE PAROU.
     A peça fica no ar o tempo que a lista der: pode ser 20 segundos, e aí
     só duas manchetes aparecem. Começando sempre da primeira, o passageiro
     veria eternamente as duas mesmas notícias, mesmo com oito no feed.
     Guardando o ponto por fonte, cada volta continua a leitura, e ao longo
     do dia todas as manchetes aparecem. */
  /* Só o navegador sabe a resolução real depois de baixar. Se a foto for
     menor que a tela, esticar destrói: melhor mostrar menor e nítida.
     1100px é o limite prático — abaixo disso o borrão aparece numa 55". */
  function medir(art){
    var foto = art.querySelector('.mat__foto');
    if(!foto) return;
    function avaliar(){
      if(!foto.naturalWidth) return;
      if(foto.naturalWidth < 1100 || foto.naturalHeight < 620) art.className += ' pequena';
      art.setAttribute('data-res', foto.naturalWidth + 'x' + foto.naturalHeight);
    }
    if(foto.complete) avaliar(); else foto.addEventListener('load', avaliar);
    // Foto que não carrega vira cartaz de manchete, não um vazio.
    foto.addEventListener('error', function(){
      art.removeAttribute('data-img');
      foto.style.display = 'none';
      var f = art.querySelector('.mat__fundo');
      if(f) f.style.display = 'none';
    });
  }
  /* Ajusta a manchete ao espaço real.
     O texto não pode passar de metade da altura: acima disso ele domina a
     tela e a foto vira pano de fundo — o contrário do que a peça deveria
     ser. Manchete curta cresce, longa encolhe. */
  function ajustarTexto(art){
    var cx = art.querySelector('.mat__txt');
    var tit = art.querySelector('.mat__tit');
    if(!cx || !tit) return;

    var n = tit.textContent.trim().length;
    // Ponto de partida pelo tamanho: 40 caracteres cabem grandes, 120 não.
    var t = n < 45 ? 5.4 : (n < 75 ? 4.6 : (n < 105 ? 3.9 : 3.3));
    tit.style.setProperty('--tit', t + 'vw');
    art.style.setProperty('--res', (t * 0.42) + 'vw');

    var teto = window.innerHeight * 0.46;
    var voltas = 0;
    while(cx.getBoundingClientRect().height > teto && t > 2.4 && voltas < 30){
      t -= 0.18;
      tit.style.setProperty('--tit', t + 'vw');
      art.style.setProperty('--res', (t * 0.42) + 'vw');
      voltas++;
    }
  }

  [].forEach.call(document.querySelectorAll('.matéria'), function(a){
    medir(a); ajustarTexto(a);
  });

  // Remede quando a peça reaparece: elemento escondido tem altura zero.
  window.addEventListener('resize', function(){
    [].forEach.call(document.querySelectorAll('.matéria'), ajustarTexto);
  });

  var CH = 'tvi.news.' + (location.search || 'x');
  var n = 0;
  try {
    var salvo = parseInt(sessionStorage.getItem(CH), 10);
    if(!isNaN(salvo) && salvo >= 0 && salvo < mats.length) n = salvo;
  } catch(e){}

  function mostrar(i){
    mats.forEach ? mats.forEach(limpa) : Array.prototype.forEach.call(mats, limpa);
    function limpa(m, k){
      // classList.remove em vez de reescrever className: o elemento carrega
      // outras classes (soimg, pequena) que o servidor e a medição puseram,
      // e reescrever apagava todas — foi o que anulou o modo "só imagem".
      m.classList.remove('on');
      if(pontos[k]) pontos[k].className = '';
    }
    mats[i].classList.add('on');
    if(pontos[i]) pontos[i].className = 'on';
    try { sessionStorage.setItem(CH, String((i + 1) % mats.length)); } catch(e){}
  }

  function tempoDe(i){
    var v = parseInt(mats[i].getAttribute('data-ms'), 10);
    return (v && v > 3000) ? v : 18000;
  }

  mostrar(n);
  if(mats.length > 1){
    (function girar(){
      setTimeout(function(){
        n = (n + 1) % mats.length;
        mostrar(n);
        girar();
      }, tempoDe(n));
    })();
  }

  /* Recarrega a cada 15 minutos, casado com o cache do servidor. Notícia
     nova entra sozinha nesse intervalo. */
  setTimeout(function(){ location.reload(); }, 900000);
})();
</script>

