<script>
(function(){
  var D = ['domingo','segunda-feira','terça-feira','quarta-feira','quinta-feira','sexta-feira','sábado'];
  var M = ['janeiro','fevereiro','março','abril','maio','junho','julho',
           'agosto','setembro','outubro','novembro','dezembro'];
  function p(n){ return n < 10 ? '0'+n : ''+n; }
  function tique(){
    var d = new Date();
    document.getElementById('hora').innerHTML =
      p(d.getHours()) + '<span class="sep' + (d.getSeconds()%2 ? ' off' : '') + '">:</span>' +
      p(d.getMinutes()) + '<small>' + p(d.getSeconds()) + '</small>';
    document.getElementById('dia').textContent =
      D[d.getDay()] + ', ' + d.getDate() + ' de ' + M[d.getMonth()] + ' de ' + d.getFullYear();
  }
  tique();
  setInterval(tique, 1000);
})();
</script>

