<script>
/* ── Economia de processador ──────────────────────────────────
   A peça vive num iframe. Enquanto o player mostra OUTRO item, este
   documento continua existindo e as animações continuam rodando — o
   Android desenha coisa que ninguém vê.

   Num Android de TV com 1 GB, isso é o que faz a troca engasgar: a peça
   nova carrega enquanto a antiga ainda anima o fundo desfocado.

   A API de visibilidade não dispara em iframe escondido por opacidade,
   então uso o IntersectionObserver, que enxerga o caso. Onde ele não
   existir (TV muito antiga), nada muda e a peça funciona como antes. */
/* Marca o documento como pronto DEPOIS da primeira pintura. É o gatilho
   dos efeitos caros — eles entram quando a tela já apareceu. */
(function(){
  function pronto(){ document.body.className = (document.body.className + ' pronto').trim(); }
  if(window.requestAnimationFrame){
    requestAnimationFrame(function(){ requestAnimationFrame(pronto); });
  } else {
    setTimeout(pronto, 50);
  }
})();

(function(){
  if(!window.IntersectionObserver) return;
  var raiz = document.body;
  var pausado = false;

  function aplicar(p){
    if(p === pausado) return;
    pausado = p;
    // animation-play-state é o único jeito de parar sem recalcular layout.
    raiz.style.setProperty('--play', p ? 'paused' : 'running');
    raiz.className = p ? (raiz.className + ' fora').trim()
                       : raiz.className.replace(/\s*fora\b/, '');
  }

  try {
    var obs = new IntersectionObserver(function(e){
      aplicar(!e[0].isIntersecting);
    }, { threshold: 0.01 });
    obs.observe(document.documentElement);
  } catch(e){}

  // Aba em segundo plano: mesma economia, caminho diferente.
  document.addEventListener('visibilitychange', function(){
    if(document.hidden) aplicar(true);
    else aplicar(false);
  });
})();
</script>
</body>
</html>
